import { ISkillCard, SkillCardContext } from '../ISkillCard.ts';

export class HardwareEnclaveCard implements ISkillCard {
  public readonly id = 'HARDWARE_ENCLAVE';
  public readonly title = '冷錢包硬體防護';
  public readonly badge = '安全隔離';
  public readonly category = 'STATS';
  public readonly iconKey = 'shield';
  public readonly maxLevel = 8;
  public readonly financeTerm = '【冷錢包 (Cold Wallet)】私鑰永不聯網的離線硬體儲存，徹底隔離駭客威脅。';

  public getDescription(currentLevel: number): string {
    const next = currentLevel + 1;
    return `受傷無敵時間延長 +${(next * 0.15).toFixed(2)} 秒；Lv 8 獲得每關抵擋一次致命傷害保險`;
  }

  public isEligible(context: SkillCardContext): boolean {
    const current = context.engine.skillLevels?.get(this.id) ?? 0;
    return current < this.maxLevel;
  }

  public apply(context: SkillCardContext, nextLevel: number): void {
    context.engine.invulnerableBonus = nextLevel * 150;
    if (nextLevel >= 8) {
      context.engine.fatalShieldReady = true;
    }
  }
}
