export const CURRENT_PASSPORT_SCHEMA_VERSION = 1;
export const DEFAULT_PASSPORT_STORAGE_KEY = 'snek_pet_passport';

/**
 * 標準化五維能力值（所有玩法世界通用，用不到的欄位可忽略）
 */
export interface SnekCoreStats {
  hp: number;     // 生命值 / 最大耐久
  atk: number;    // 攻擊力 / 基礎威力
  def: number;    // 防禦力 / 護甲減傷
  speed: number;  // 移動速度 / 敏捷反應
  luck: number;   // 幸運值（影響暴擊率與稀有掉落加成，基礎 20 代表 20% 暴擊率）
}

/**
 * 標準化武器附魔標籤（跨玩法通用詞條）
 */
export type WeaponEnchantmentTag =
  | 'MULTI_SHOT'   // 多重發射（發射物數量 +1）
  | 'PIERCE'       // 貫穿強化（穿透目標數 +1）
  | 'EXPLOSIVE'    // 爆破震波（命中產生或擴大範圍波及半徑）
  | 'FROST_BITE'   // 寒霜緩速（命中減緩敵方速度並附帶額外傷害）
  | 'VAMPIRIC'     // 生命汲取（擊殺回復生命值）
  | 'CRIT_BOOST'   // 致命專注（幸運/暴擊率 +12，暴擊倍率提升）
  | 'HASTE';       // 極速念力（攻擊頻率提升 18%）

/**
 * 單手念力武器流派分類（含遠程銃槍與 survival-kit 念力戰斧/戰錘）
 */
export type WeaponArchetype =
  | 'PULSE'
  | 'SPREAD'
  | 'PIERCE'
  | 'EXPLOSIVE'
  | 'TELEKINETIC_AXE'
  | 'TELEKINETIC_HAMMER';

/**
 * Snek 寵物心情氣泡類型（對應 kenney_emotes-pack 圖片）
 */
export type SnekEmoteType =
  | 'heart'
  | 'hearts'
  | 'happy'
  | 'angry'
  | 'alert'
  | 'exclamation'
  | 'star'
  | 'stars'
  | 'idea'
  | 'cash'
  | 'sleep';

/**
 * 頭頂右上方唯一念力主武器規格
 */
export interface EquippedWeaponSpec {
  weaponId: string;
  name: string;
  archetype: WeaponArchetype;
  tier: number;               // 階級 Tier 1 ~ 6
  upgradeLevel: number;       // 工匠強化等級 +0 ~ +10
  modelUrl: string;           // 3D GLB 模型路徑
  iconUrl: string;            // 2D UI 圖示路徑
  projectileModelUrl: string; // 投射物 3D GLB 路徑
  bonusStats: Partial<SnekCoreStats>;
  attackSpeedMultiplier: number;
  shotCount: number;
  spreadAngle: number;
  pierceCount: number;
  explosionRadius: number;
  enchantmentTags: WeaponEnchantmentTag[];
}

/**
 * 儲存於 localStorage 的專屬寵物護照（含 schemaVersion 供未來無損升版）
 */
export interface SnekPetPassport {
  schemaVersion: number;
  petId: string;
  petName: string;
  updatedAt: number;
  level: number;
  exp: number;
  affection: number;          // 親密度 / 飽食度 (0 ~ 100)
  moodEmote: SnekEmoteType;
  baseStats: SnekCoreStats;
  equippedWeapon: EquippedWeaponSpec;
  wallet: {
    gold: number;
  };
  inventory: Record<string, number>;
  backpackCapacity?: number;
  stash?: Record<string, number>;
  unlockedWeapons?: string[];
  unlockedEnchantments?: WeaponEnchantmentTag[];
  worldProgress: Record<
    string,
    {
      highestStage: number;
      clears: number;
    }
  >;
}

/**
 * 結合「寵物本體五維 + 武器基礎加成 + 工匠強化 (+N) + 附魔標籤 + 親密度」後的最終戰鬥面板
 */
export interface ResolvedSnekCombatProfile {
  stats: SnekCoreStats;
  critChance: number;         // 0.0 ~ 0.85
  critMultiplier: number;     // 預設 1.8，CRIT_BOOST 可提升
  attackSpeed: number;        // 每秒攻擊次數
  shotCount: number;
  spreadAngle: number;
  pierceCount: number;
  explosionRadius: number;
  vampiricHealOnKill: number;
  frostSlowRatio: number;
  enchantmentTags: WeaponEnchantmentTag[];
  weapon: EquippedWeaponSpec;
}

/**
 * 玩法世界回歸家園時提交的「冒險結算單」
 */
export interface ExpeditionReceipt {
  worldId: string;
  durationSec: number;
  stageReached: number;
  outcome: 'EXTRACTED' | 'DEFEATED';
  goldEarned: number;
  expEarned: number;
  killsCount: number;
  itemsFound?: Record<string, number>;
  upgradedWeaponTier?: number;
}

/**
 * 結算單經 PortalHost 驗證並寫入護照後的結果報告
 */
export interface ExpeditionSettlementResult {
  accepted: boolean;
  finalGoldAdded: number;
  finalExpAdded: number;
  leveledUp: boolean;
  newLevel: number;
  updatedPassport: Readonly<SnekPetPassport>;
}

/**
 * 軌道 A (LocalPlugin)：傳遞給同專案玩法世界的 SDK 上下文
 */
export interface SnekWorldContext {
  worldId: string;
  /** 取得深層凍結的唯讀寵物護照快照 */
  getPassport(): Readonly<SnekPetPassport>;
  /** 取得已結算五維與武器附魔的戰鬥面板 */
  getCombatProfile(): ResolvedSnekCombatProfile;
  /** 將冒險結果結算並傳送回家園 */
  jackOut(receipt: Omit<ExpeditionReceipt, 'worldId'>): ExpeditionSettlementResult;
}

/**
 * 軌道 A (LocalPlugin)：同專案玩法世界標準插件介面
 */
export interface ISnekWorldPlugin {
  readonly worldId: string;
  readonly title: string;
  readonly description: string;
  mount(container: HTMLElement, context: SnekWorldContext): () => void;
}

/**
 * 舊版護照升版遷移器函式簽章
 */
export type PassportMigrator = (raw: Record<string, any>) => Record<string, any>;
