export function createWeaponFromTier(
  tierIndex: number,
  preserveUpgradeLevel: number = 0,
  preserveEnchantments: WeaponEnchantmentTag[] = []
): EquippedWeaponSpec {
  const clampedIdx = Math.max(0, Math.min(SDK_WEAPON_TIERS.length - 1, tierIndex));
  const template = SDK_WEAPON_TIERS[clampedIdx];
  return {
    ...template,
    bonusStats: { ...template.bonusStats },
    upgradeLevel: preserveUpgradeLevel,
    enchantmentTags: [...preserveEnchantments],
  };
}
