import * as THREE from 'three';
import { GLTFModelLoader } from '../core/GLTFModelLoader.ts';

export interface RoomBounds {
  minX: number;
  maxX: number;
  minZ: number;
  maxZ: number;
}

export class DungeonRoom {
  public group: THREE.Group;
  public bounds: RoomBounds = {
    minX: -7.5,
    maxX: 7.5,
    minZ: -9.5,
    maxZ: 9.5,
  };

  private portalMesh: THREE.Mesh | null = null;
  private portalRing: THREE.Mesh | null = null;
  private portalRuneDisk: THREE.Mesh | null = null;
  private portalLight: THREE.PointLight | null = null;
  private fallbackWallsGroup: THREE.Group;
  private graveyardPropsGroup: THREE.Group;
  private isPortalActive: boolean = false;
  private isDestroyed: boolean = false;
  private materials: THREE.Material[] = [];
  private geometries: THREE.BufferGeometry[] = [];

  constructor(scene: THREE.Scene) {
    this.group = new THREE.Group();
    scene.add(this.group);

    this.fallbackWallsGroup = new THREE.Group();
    this.group.add(this.fallbackWallsGroup);

    this.graveyardPropsGroup = new THREE.Group();
    this.group.add(this.graveyardPropsGroup);

    this.buildFloor();
    this.buildWalls();
    this.buildTorches();
    this.buildExitPortal();
    this.loadGraveyardEnvironment();
  }

  private createTileTexture(): THREE.CanvasTexture {
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 512;
    const ctx = canvas.getContext('2d')!;

    ctx.fillStyle = '#161c28';
    ctx.fillRect(0, 0, 512, 512);

    const tileSize = 128;
    for (let x = 0; x < 4; x++) {
      for (let y = 0; y < 4; y++) {
        const px = x * tileSize;
        const py = y * tileSize;

        const grad = ctx.createLinearGradient(px, py, px + tileSize, py + tileSize);
        const shade = 28 + ((x * 3 + y * 7) % 15);
        grad.addColorStop(0, `rgb(${shade + 5}, ${shade + 10}, ${shade + 18})`);
        grad.addColorStop(1, `rgb(${shade - 4}, ${shade}, ${shade + 6})`);
        ctx.fillStyle = grad;
        ctx.fillRect(px + 3, py + 3, tileSize - 6, tileSize - 6);

        ctx.strokeStyle = 'rgba(255, 255, 255, 0.04)';
        ctx.strokeRect(px + 4, py + 4, tileSize - 8, tileSize - 8);

        ctx.fillStyle = 'rgba(0, 230, 118, 0.025)';
        ctx.fillRect(px + 20, py + 20, 15, 2);
      }
    }

    const texture = new THREE.CanvasTexture(canvas);
    texture.wrapS = THREE.RepeatWrapping;
    texture.wrapT = THREE.RepeatWrapping;
    texture.repeat.set(4, 5);
    return texture;
  }

  private buildFloor(): void {
    const floorGeo = new THREE.PlaneGeometry(20, 26);
    this.geometries.push(floorGeo);

    const tileTexture = this.createTileTexture();
    const floorMat = new THREE.MeshStandardMaterial({
      map: tileTexture,
      roughness: 0.78,
      metalness: 0.1,
    });
    this.materials.push(floorMat);

    const texLoader = new THREE.TextureLoader();
    texLoader.load(
      './assets/dungeon3d/dungeon_stone_floor.jpg',
      (texture) => {
        texture.wrapS = THREE.RepeatWrapping;
        texture.wrapT = THREE.RepeatWrapping;
        texture.repeat.set(3, 4);
        floorMat.map = texture;
        floorMat.needsUpdate = true;
      },
      undefined,
      () => {
        // Fallback to procedural canvas texture seamlessly
      }
    );

    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.position.y = 0;
    floor.receiveShadow = true;
    this.group.add(floor);
  }

  private buildWalls(): void {
    const wallMat = new THREE.MeshStandardMaterial({
      color: 0x1b2333,
      roughness: 0.85,
      metalness: 0.15,
    });
    const wallTrimMat = new THREE.MeshStandardMaterial({
      color: 0x101622,
      roughness: 0.6,
      metalness: 0.4,
    });
    this.materials.push(wallMat, wallTrimMat);

    const wallThickness = 1.0;
    const wallHeight = 0.65; // Low curb foundation underneath the 3D Graveyard stone walls

    // East Curb (+X)
    const eastGeo = new THREE.BoxGeometry(wallThickness, wallHeight, 24 + wallThickness);
    this.geometries.push(eastGeo);
    const eastWall = new THREE.Mesh(eastGeo, wallMat);
    eastWall.position.set(9 + wallThickness / 2, wallHeight / 2, 0);
    this.fallbackWallsGroup.add(eastWall);

    // West Curb (-X)
    const westGeo = new THREE.BoxGeometry(wallThickness, wallHeight, 24 + wallThickness);
    this.geometries.push(westGeo);
    const westWall = new THREE.Mesh(westGeo, wallMat);
    westWall.position.set(-9 - wallThickness / 2, wallHeight / 2, 0);
    this.fallbackWallsGroup.add(westWall);

    // South Curb (+Z)
    const southGeo = new THREE.BoxGeometry(18, wallHeight, wallThickness);
    this.geometries.push(southGeo);
    const southWall = new THREE.Mesh(southGeo, wallMat);
    southWall.position.set(0, wallHeight / 2, 12 + wallThickness / 2);
    this.fallbackWallsGroup.add(southWall);

    // North Curb (-Z, with portal gate opening in the middle)
    const northSegmentGeo = new THREE.BoxGeometry(7, wallHeight, wallThickness);
    this.geometries.push(northSegmentGeo);

    const northLeft = new THREE.Mesh(northSegmentGeo, wallMat);
    northLeft.position.set(-5.5, wallHeight / 2, -12 - wallThickness / 2);
    this.fallbackWallsGroup.add(northLeft);

    const northRight = new THREE.Mesh(northSegmentGeo, wallMat);
    northRight.position.set(5.5, wallHeight / 2, -12 - wallThickness / 2);
    this.fallbackWallsGroup.add(northRight);
  }

  private buildTorches(): void {
    const flameMat = new THREE.MeshBasicMaterial({
      color: 0x00e676,
    });
    this.materials.push(flameMat);

    const flameGeo = new THREE.ConeGeometry(0.24, 0.55, 6);
    this.geometries.push(flameGeo);

    const torchPositions = [
      { x: -7.6, z: -10.2 },
      { x: 7.6, z: -10.2 },
      { x: -7.6, z: 10.2 },
      { x: 7.6, z: 10.2 },
      { x: -7.6, z: 0 },
      { x: 7.6, z: 0 },
    ];

    torchPositions.forEach((pos) => {
      const flame = new THREE.Mesh(flameGeo, flameMat);
      flame.position.set(pos.x, 2.35, pos.z);
      this.group.add(flame);

      const light = new THREE.PointLight(0x00e676, 1.1, 8);
      light.position.set(pos.x, 2.6, pos.z);
      this.group.add(light);
    });
  }

  private placeGraveyardProp(
    url: string,
    placements: Array<{ x: number; y?: number; z: number; rotY?: number; scale?: number }>
  ): void {
    GLTFModelLoader.getInstance()
      .load(url)
      .then((gltf) => {
        if (this.isDestroyed) return;
        gltf.scene.traverse((child) => {
          if (child instanceof THREE.Mesh && child.material) {
            const mat = child.material as THREE.MeshStandardMaterial;
            if (mat.map) {
              mat.map.colorSpace = THREE.SRGBColorSpace;
            }
          }
        });

        for (const p of placements) {
          const { scene: clone } = GLTFModelLoader.getInstance().instantiate(gltf);
          const s = p.scale ?? 2.2;
          clone.scale.setScalar(s);
          clone.position.set(p.x, p.y ?? 0, p.z);
          if (p.rotY !== undefined) {
            clone.rotation.y = p.rotY;
          }
          this.graveyardPropsGroup.add(clone);
        }
      })
      .catch(() => {
        // Ignore in headless test environment
      });
  }

  private loadGraveyardEnvironment(): void {
    const base = './assets/dungeon3d/kenney/graveyard-kit';

    // 1. Perimeter Stone Walls & Damaged Stone Walls along West (-9.2) and East (+9.2)
    const sideWalls: Array<{ x: number; z: number; rotY: number; scale: number }> = [];
    const damagedWalls: Array<{ x: number; z: number; rotY: number; scale: number }> = [];
    for (let z = -10; z <= 10; z += 2.5) {
      if (Math.abs(z) % 5 === 0) {
        damagedWalls.push({ x: -9.2, z, rotY: Math.PI / 2, scale: 2.5 });
        damagedWalls.push({ x: 9.2, z, rotY: -Math.PI / 2, scale: 2.5 });
      } else {
        sideWalls.push({ x: -9.2, z, rotY: Math.PI / 2, scale: 2.5 });
        sideWalls.push({ x: 9.2, z, rotY: -Math.PI / 2, scale: 2.5 });
      }
    }
    // North & South Stone Walls
    for (const x of [-7.5, -5.0, 5.0, 7.5]) {
      sideWalls.push({ x, z: -12.2, rotY: 0, scale: 2.5 });
    }
    for (let x = -7.5; x <= 7.5; x += 3.0) {
      sideWalls.push({ x, z: 12.2, rotY: Math.PI, scale: 2.5 });
    }
    this.placeGraveyardProp(`${base}/stone-wall.glb`, sideWalls);
    this.placeGraveyardProp(`${base}/stone-wall-damaged.glb`, damagedWalls);

    // 2. Corner & Gate Stone Columns
    this.placeGraveyardProp(`${base}/stone-wall-column.glb`, [
      { x: -9.2, z: -12.2, scale: 2.8 },
      { x: 9.2, z: -12.2, scale: 2.8 },
      { x: -9.2, z: 12.2, scale: 2.8 },
      { x: 9.2, z: 12.2, scale: 2.8 },
      { x: -3.2, z: -12.2, scale: 2.8 },
      { x: 3.2, z: -12.2, scale: 2.8 },
    ]);

    // 3. North Portal Crypt Archway & Obelisks
    this.placeGraveyardProp(`${base}/crypt-small.glb`, [
      { x: 0, z: -12.6, rotY: 0, scale: 2.4 },
    ]);
    this.placeGraveyardProp(`${base}/pillar-obelisk.glb`, [
      { x: -2.5, z: -10.8, scale: 2.3 },
      { x: 2.5, z: -10.8, scale: 2.3 },
    ]);

    // 4. Torch Pillars + Fire Baskets
    const torchCoords = [
      { x: -7.6, z: -10.2 },
      { x: 7.6, z: -10.2 },
      { x: -7.6, z: 10.2 },
      { x: 7.6, z: 10.2 },
      { x: -7.6, z: 0 },
      { x: 7.6, z: 0 },
    ];
    this.placeGraveyardProp(
      `${base}/pillar-large.glb`,
      torchCoords.map((c) => ({ x: c.x, y: 0, z: c.z, scale: 1.8 }))
    );
    this.placeGraveyardProp(
      `${base}/fire-basket.glb`,
      torchCoords.map((c) => ({ x: c.x, y: 1.9, z: c.z, scale: 2.2 }))
    );

    // 5. Atmospheric Graveyard Props along Room Borders (Gravestones, Carved Pumpkins, Coffins, Crooked Pines, Rocks)
    this.placeGraveyardProp(`${base}/gravestone-cross-large.glb`, [
      { x: -7.4, z: -6.5, rotY: 0.35, scale: 2.1 },
      { x: 7.4, z: -6.5, rotY: -0.35, scale: 2.1 },
      { x: -7.4, z: 6.5, rotY: 0.25, scale: 2.1 },
    ]);
    this.placeGraveyardProp(`${base}/gravestone-decorative.glb`, [
      { x: -7.5, z: -3.2, rotY: 0.4, scale: 2.1 },
      { x: 7.5, z: 3.2, rotY: -0.4, scale: 2.1 },
      { x: 7.4, z: 6.5, rotY: -0.25, scale: 2.1 },
    ]);
    this.placeGraveyardProp(`${base}/coffin-old.glb`, [
      { x: -6.8, z: -10.8, rotY: 0.3, scale: 2.0 },
      { x: 6.8, z: -10.8, rotY: -0.3, scale: 2.0 },
    ]);
    this.placeGraveyardProp(`${base}/pumpkin-carved.glb`, [
      { x: -2.2, z: -10.0, rotY: 0.4, scale: 2.2 },
      { x: 2.2, z: -10.0, rotY: -0.4, scale: 2.2 },
      { x: -6.8, z: 9.8, rotY: 0.6, scale: 2.2 },
      { x: 6.8, z: 9.8, rotY: -0.6, scale: 2.2 },
    ]);
    this.placeGraveyardProp(`${base}/pine-crooked.glb`, [
      { x: -8.3, z: -8.5, rotY: 0.5, scale: 2.2 },
      { x: 8.3, z: -8.5, rotY: -0.5, scale: 2.2 },
      { x: -8.3, z: 8.5, rotY: 1.2, scale: 2.2 },
      { x: 8.3, z: 8.5, rotY: -1.2, scale: 2.2 },
    ]);
    this.placeGraveyardProp(`${base}/rocks.glb`, [
      { x: -7.8, z: -4.8, rotY: 0.8, scale: 2.0 },
      { x: 7.8, z: -4.8, rotY: -0.8, scale: 2.0 },
      { x: -7.8, z: 4.8, rotY: 1.6, scale: 2.0 },
      { x: 7.8, z: 4.8, rotY: -1.6, scale: 2.0 },
    ]);
  }

  private buildExitPortal(): void {
    const ringGeo = new THREE.TorusGeometry(1.6, 0.15, 8, 24);
    this.geometries.push(ringGeo);

    const ringMat = new THREE.MeshStandardMaterial({
      color: 0x334455,
      roughness: 0.4,
      metalness: 0.8,
    });
    this.materials.push(ringMat);

    this.portalRing = new THREE.Mesh(ringGeo, ringMat);
    this.portalRing.rotation.x = Math.PI / 2;
    this.portalRing.position.set(0, 0.1, -10.5);
    this.group.add(this.portalRing);

    const runeCircleGeo = new THREE.CircleGeometry(1.5, 32);
    this.geometries.push(runeCircleGeo);
    const runeMat = new THREE.MeshBasicMaterial({
      transparent: true,
      opacity: 0.25,
      side: THREE.DoubleSide,
      depthWrite: false,
    });
    this.materials.push(runeMat);

    const texLoader = new THREE.TextureLoader();
    texLoader.load(
      './assets/dungeon3d/portal_runic_ring.png',
      (tex) => {
        runeMat.map = tex;
        runeMat.needsUpdate = true;
      },
      undefined,
      () => {
        texLoader.load('./assets/dungeon3d/portal_runic_ring.jpg', (fallbackTex) => {
          runeMat.map = fallbackTex;
          runeMat.needsUpdate = true;
        });
      }
    );

    this.portalRuneDisk = new THREE.Mesh(runeCircleGeo, runeMat);
    this.portalRuneDisk.rotation.x = -Math.PI / 2;
    this.portalRuneDisk.position.set(0, 0.04, -10.5);
    this.group.add(this.portalRuneDisk);

    const cylinderGeo = new THREE.CylinderGeometry(1.4, 1.4, 2.5, 16, 1, true);
    this.geometries.push(cylinderGeo);

    const portalMat = new THREE.MeshBasicMaterial({
      color: 0x00ffff,
      transparent: true,
      opacity: 0.15,
      side: THREE.DoubleSide,
    });
    this.materials.push(portalMat);

    this.portalMesh = new THREE.Mesh(cylinderGeo, portalMat);
    this.portalMesh.position.set(0, 1.25, -10.5);
    this.portalMesh.visible = false;
    this.group.add(this.portalMesh);

    this.portalLight = new THREE.PointLight(0x00e676, 0, 10);
    this.portalLight.position.set(0, 1.5, -10.5);
    this.group.add(this.portalLight);
  }

  public setPortalActive(active: boolean): void {
    this.isPortalActive = active;
    if (this.portalMesh) {
      this.portalMesh.visible = active;
    }
    if (this.portalRuneDisk) {
      (this.portalRuneDisk.material as THREE.MeshBasicMaterial).opacity = active ? 0.9 : 0.25;
    }
    if (this.portalLight) {
      this.portalLight.intensity = active ? 4.0 : 0;
      this.portalLight.color.setHex(0x00e676);
    }
    if (this.portalRing && this.portalRing.material instanceof THREE.MeshStandardMaterial) {
      this.portalRing.material.emissive.setHex(active ? 0x00e676 : 0x000000);
      this.portalRing.material.emissiveIntensity = active ? 1.0 : 0;
    }
  }

  public update(delta: number): void {
    if (this.portalRuneDisk) {
      this.portalRuneDisk.rotation.z += delta * (this.isPortalActive ? 1.2 : 0.15);
    }

    if (this.isPortalActive && this.portalMesh) {
      this.portalMesh.rotation.y += delta * 2.2;
      const pulse = (Math.sin(performance.now() * 0.005) + 1) * 0.5;
      (this.portalMesh.material as THREE.MeshBasicMaterial).opacity = 0.25 + pulse * 0.25;
      if (this.portalLight) {
        this.portalLight.intensity = 3.0 + pulse * 2.5;
      }
    }
  }

  public checkPortalCollision(x: number, z: number): boolean {
    if (!this.isPortalActive) return false;
    const dx = x - 0;
    const dz = z - (-10.5);
    return Math.hypot(dx, dz) < 1.8;
  }

  public clampPosition(x: number, z: number): { x: number; z: number } {
    return {
      x: Math.max(this.bounds.minX, Math.min(this.bounds.maxX, x)),
      z: Math.max(this.bounds.minZ, Math.min(this.bounds.maxZ, z)),
    };
  }

  public destroy(): void {
    this.isDestroyed = true;
    this.geometries.forEach((g) => g.dispose());
    this.materials.forEach((m) => m.dispose());
    this.geometries = [];
    this.materials = [];
  }
}
