import * as THREE from 'three';
import { buildFloorMonsterSpawns } from '../data/monstersCatalog.ts';
import { LootChest3D } from '../entities/LootChest3D.ts';
import { Monster3D } from '../entities/Monster3D.ts';

export class FloorDirector {
  public static isBossFloor(floor: number): boolean {
    return floor > 0 && floor % 5 === 0;
  }

  public static spawnFloorMonsters(scene: THREE.Scene, floor: number): Monster3D[] {
    const specs = buildFloorMonsterSpawns(floor);
    return specs.map((s) => new Monster3D(scene, s.config, s.x, s.z));
  }

  public static areAllMonstersDefeated(monsters: Monster3D[]): boolean {
    for (let i = 0; i < monsters.length; i++) {
      if (!monsters[i].isDead) return false;
    }
    return true;
  }

  public static spawnClearRewardChest(scene: THREE.Scene, floor: number): LootChest3D {
    return new LootChest3D(scene, 0, 0, 30 + floor * 15);
  }
}
