import { I18nService } from '../../../platform/I18nService.ts';
import { SaveManager } from '../save/SaveManager.ts';
import { BossDefeatSnapshot, LevelCheckpointSnapshot } from '../save/types.ts';

export interface BossSelectModalOptions {
  saveManager?: SaveManager;
  onStartNewRun: () => void;
  onSelectBoss: (snapshot: BossDefeatSnapshot) => void;
  onResumeCheckpoint?: (checkpoint: LevelCheckpointSnapshot) => void;
  onClose?: () => void;
}

export interface BossRosterItem {
  stage: number;
  type: string;
  nameZh: string;
  nameZhCn: string;
  nameEn: string;
  portrait: string;
}

export const BOSS_ROSTER: BossRosterItem[] = [
  { stage: 1, type: 'DOGE_KING', nameZh: '始祖神犬', nameZhCn: '始祖神犬', nameEn: 'Doge King', portrait: './assets/bosses/portraits/boss_doge_portrait.png' },
  { stage: 2, type: 'PEPE_FROG', nameZh: '悲傷蛙神', nameZhCn: '悲伤蛙神', nameEn: 'Pepe the Frog', portrait: './assets/bosses/portraits/boss_pepe_portrait.png' },
  { stage: 3, type: 'WHALE_GOD', nameZh: '萬億巨鯨', nameZhCn: '万亿巨鲸', nameEn: 'Whale God', portrait: './assets/bosses/portraits/boss_whale_portrait.png' },
  { stage: 4, type: 'WIF_HAT', nameZh: '戴帽神柴', nameZhCn: '戴帽神柴', nameEn: 'Dogwifhat', portrait: './assets/bosses/portraits/boss_wif_portrait.png' },
  { stage: 5, type: 'BONK_MASTER', nameZh: '球棒制裁者', nameZhCn: '球棒制裁者', nameEn: 'Bonk Master', portrait: './assets/bosses/portraits/boss_bonk_portrait.png' },
  { stage: 6, type: 'POPCAT_OVERLORD', nameZh: '魔性啵啵貓', nameZhCn: '魔性啵啵猫', nameEn: 'Popcat Overlord', portrait: './assets/bosses/portraits/boss_popcat_portrait.png' },
  { stage: 7, type: 'FLOKI_VIKING', nameZh: '維京海盜王', nameZhCn: '维京海盗王', nameEn: 'Floki the Viking', portrait: './assets/bosses/portraits/boss_floki_portrait.png' },
  { stage: 8, type: 'MOODENG_TERROR', nameZh: '暴躁彈跳豬', nameZhCn: '暴躁弹跳猪', nameEn: 'Moo Deng', portrait: './assets/bosses/portraits/boss_moodeng_portrait.png' },
  { stage: 9, type: 'WOJAK_TRADER', nameZh: '麥當勞哭哭男', nameZhCn: '麦当劳哭哭男', nameEn: 'Wojak Down-Only', portrait: './assets/bosses/portraits/boss_wojak_portrait.png' },
  { stage: 10, type: 'GIGACHAD_OMEGA', nameZh: '終極完美型男', nameZhCn: '终极完美型男', nameEn: 'GigaChad Ascended', portrait: './assets/bosses/portraits/boss_gigachad_portrait.png' },
];

export class BossSelectModal {
  private saveManager: SaveManager;
  private onStartNewRun: () => void;
  private onSelectBoss: (snapshot: BossDefeatSnapshot) => void;
  private onResumeCheckpoint?: (checkpoint: LevelCheckpointSnapshot) => void;
  private onClose?: () => void;
  private element: HTMLElement | null = null;
  private unsubscribeLocale: (() => void) | null = null;

  constructor(options: BossSelectModalOptions) {
    this.saveManager = options.saveManager ?? SaveManager.getInstance();
    this.onStartNewRun = options.onStartNewRun;
    this.onSelectBoss = options.onSelectBoss;
    this.onResumeCheckpoint = options.onResumeCheckpoint;
    this.onClose = options.onClose;
  }

  public render(): HTMLElement {
    const i18n = I18nService.getInstance();
    const modalEl = document.createElement('div');
    modalEl.id = 'boss-select-modal';
    modalEl.className = 'modal-overlay boss-select-overlay active';

    // Touch event isolation to prevent joystick capture and preserve native touch scrolling
    modalEl.addEventListener('touchstart', (e) => {
      e.stopPropagation();
    }, { passive: true });
    modalEl.addEventListener('touchmove', (e) => {
      e.stopPropagation();
    }, { passive: true });
    modalEl.addEventListener('touchend', (e) => {
      e.stopPropagation();
    }, { passive: true });

    this.element = modalEl;
    this.updateContent();

    if (this.unsubscribeLocale) {
      this.unsubscribeLocale();
    }
    this.unsubscribeLocale = i18n.onLocaleChange(() => {
      this.updateContent();
    });

    return modalEl;
  }

  public updateContent(): void {
    if (!this.element) return;
    const i18n = I18nService.getInstance();
    const curLocale = i18n.getLocale();
    const isEn = curLocale === 'en';
    const isZhCn = curLocale === 'zh-CN';

    const title = i18n.t('bossSelect.title') || 'BOSS & STAGE SELECT';
    const subtitle = i18n.t('bossSelect.subtitle') || 'Select starting stage or challenge a boss directly';
    const newRunTitle = i18n.t('bossSelect.newRunTitle') || 'NEW RUN (STAGE 1)';
    const newRunDesc = i18n.t('bossSelect.newRunDesc') || 'Start fresh from Stage 1 with default level 1 stats';
    const newRunAction = i18n.t('bossSelect.newRunAction') || 'START';
    const defeatedBadge = i18n.t('bossSelect.challengeBtn') || '可挑戰';
    const lockedBadge = i18n.t('bossSelect.lockedBadge') || '未解鎖';
    const stageLabel = i18n.t('hud.stage') || 'STAGE';

    const cardsHtml = BOSS_ROSTER.map((item) => {
      const isDefeated = this.saveManager.isBossDefeated(item.stage);
      const badgeText = isDefeated ? defeatedBadge : lockedBadge;
      const isFinalBoss = item.stage === 10;
      const finalClass = isFinalBoss ? ' final-boss' : '';

      return `
        <button class="boss-card${finalClass} ${isDefeated ? 'unlocked' : 'locked'}" data-stage="${item.stage}" ${!isDefeated ? 'disabled' : ''}>
          <div class="boss-card-media">
            <img src="${item.portrait}" alt="${item.nameEn}" class="boss-card-img ${isDefeated ? 'unlocked' : 'locked'}" />
          </div>
          <div class="boss-card-meta">
            <span class="boss-card-stage">${stageLabel} ${item.stage}</span>
            <div class="boss-card-names">
              ${isEn
                ? `<span class="boss-name-en primary">${item.nameEn}</span>`
                : `<span class="boss-name-zh">${isZhCn ? item.nameZhCn : item.nameZh}</span><span class="boss-name-en">${item.nameEn}</span>`
              }
            </div>
            <span class="boss-card-badge ${isDefeated ? 'defeated' : 'locked'}">${badgeText}</span>
          </div>
        </button>
      `;
    }).join('');

    const checkpoint = this.saveManager.getLevelCheckpoint();
    let resumeCardHtml = '';
    if (checkpoint) {
      const resumeTitle = i18n.t('bossSelect.resumeTitle') || '從記錄點繼續';
      const resumeDescTemplate = i18n.t('bossSelect.resumeDesc') || 'Lv.{level} · Stage {stage} · {kills} Kills';
      const resumeDesc = resumeDescTemplate
        .replace('{level}', String(checkpoint.level))
        .replace('{stage}', String(checkpoint.stage))
        .replace('{kills}', String(checkpoint.kills));
      const resumeAction = i18n.t('bossSelect.resumeAction') || '繼續';

      resumeCardHtml = `
        <button id="btn-resume-checkpoint" class="btn-resume-checkpoint" type="button" aria-label="${resumeTitle}">
          <div class="resume-checkpoint-left">
            <div class="resume-checkpoint-icon-badge">
              <svg viewBox="0 0 24 24" class="resume-checkpoint-play-svg">
                <polygon points="7,4 20,12 7,20"></polygon>
              </svg>
            </div>
            <div class="resume-checkpoint-content">
              <span class="resume-checkpoint-title">${resumeTitle}</span>
              <span class="resume-checkpoint-desc">${resumeDesc}</span>
            </div>
          </div>
          <div class="resume-checkpoint-action-badge">
            <span class="resume-checkpoint-action-text">${resumeAction}</span>
            <svg viewBox="0 0 24 24" class="resume-checkpoint-arrow-svg">
              <polyline points="9 18 15 12 9 6"></polyline>
            </svg>
          </div>
        </button>
      `;
    }

    this.element.innerHTML = `
      <div class="game-modal boss-select-modal">
        <div class="boss-select-header">
          <h2 class="boss-select-title">${title}</h2>
          <p class="boss-select-subtitle">${subtitle}</p>
        </div>

        <div class="boss-select-quickstart">
          ${resumeCardHtml}
          <button id="btn-new-run" class="btn-new-run" type="button" aria-label="${newRunTitle}">
            <div class="new-run-left">
              <div class="new-run-icon-badge">
                <svg viewBox="0 0 24 24" class="new-run-play-svg">
                  <polygon points="7,4 20,12 7,20"></polygon>
                </svg>
              </div>
              <div class="new-run-content">
                <span class="new-run-title">${newRunTitle}</span>
                <span class="new-run-desc">${newRunDesc}</span>
              </div>
            </div>
            <div class="new-run-action-badge">
              <span class="new-run-action-text">${newRunAction}</span>
              <svg viewBox="0 0 24 24" class="new-run-arrow-svg">
                <polyline points="9 18 15 12 9 6"></polyline>
              </svg>
            </div>
          </button>
        </div>

        <div class="boss-grid-2col">
          ${cardsHtml}
        </div>
      </div>
    `;

    // Event Bindings
    const resumeBtn = this.element.querySelector('#btn-resume-checkpoint');
    if (resumeBtn && checkpoint) {
      let resumeTriggered = false;
      const handleResume = (e: Event) => {
        e.stopPropagation();
        if (resumeTriggered) return;
        resumeTriggered = true;
        this.hide();
        this.onResumeCheckpoint?.(checkpoint);
        setTimeout(() => { resumeTriggered = false; }, 350);
      };

      resumeBtn.addEventListener('click', handleResume);
      resumeBtn.addEventListener('touchend', (e) => {
        e.preventDefault();
        handleResume(e);
      });
    }

    const newRunBtn = this.element.querySelector('#btn-new-run');
    let newRunTriggered = false;
    const handleStartNewRun = (e: Event) => {
      e.stopPropagation();
      if (newRunTriggered) return;
      newRunTriggered = true;
      this.saveManager.clearLevelCheckpoint();
      this.hide();
      this.onStartNewRun();
      setTimeout(() => { newRunTriggered = false; }, 350);
    };

    newRunBtn?.addEventListener('click', handleStartNewRun);
    newRunBtn?.addEventListener('touchend', (e) => {
      e.preventDefault();
      handleStartNewRun(e);
    });

    const unlockedCards = this.element.querySelectorAll<HTMLElement>('.boss-card.unlocked');
    unlockedCards.forEach((card) => {
      let cardTriggered = false;
      const handleSelectCard = (e: Event) => {
        e.stopPropagation();
        if (cardTriggered) return;
        cardTriggered = true;
        const stageStr = card.getAttribute('data-stage');
        const stage = Number(stageStr);
        const snapshot = this.saveManager.getSnapshot(stage);
        if (snapshot) {
          this.saveManager.clearLevelCheckpoint();
          this.hide();
          this.onSelectBoss(snapshot);
        }
        setTimeout(() => { cardTriggered = false; }, 350);
      };

      card.addEventListener('click', handleSelectCard);
      card.addEventListener('touchend', (e) => {
        e.preventDefault();
        handleSelectCard(e);
      });
    });
  }

  public show(): void {
    if (this.element) {
      this.updateContent();
      this.element.classList.add('active');
      this.element.style.display = 'flex';
    }
  }

  public hide(): void {
    if (this.element) {
      this.element.classList.remove('active');
      this.element.style.display = 'none';
    }
    this.onClose?.();
  }

  public destroy(): void {
    if (this.unsubscribeLocale) {
      this.unsubscribeLocale();
      this.unsubscribeLocale = null;
    }
    if (this.element && this.element.parentElement) {
      this.element.parentElement.removeChild(this.element);
    }
    this.element = null;
  }
}
