import * as THREE from 'three';
import {
  ArtisanForgeService,
  ResolvedSnekCombatProfile,
  SnekEmoteType,
  SnekPassportStorage,
  SnekPetPassport,
  TELEKINETIC_MUZZLE_OFFSET,
} from '../../../sdk/snek-pet/index.ts';
import { Dungeon3DStage } from '../core/Dungeon3DStage.ts';
import { TouchJoystick } from '../core/TouchJoystick.ts';
import { DamageText3D } from '../entities/DamageText3D.ts';
import { Hero3D } from '../entities/Hero3D.ts';
import { Projectile3D } from '../entities/Projectile3D.ts';
import { HomesteadRoom3D, HomesteadStationSpec } from './HomesteadRoom3D.ts';

export interface HomesteadEngineCallbacks {
  onStationChange: (station: HomesteadStationSpec | null) => void;
  onPassportSync: (passport: SnekPetPassport, profile: ResolvedSnekCombatProfile) => void;
}

export interface HomesteadEngineOptions {
  container: HTMLElement;
  overlayContainer: HTMLElement;
  passportStorage?: SnekPassportStorage;
  callbacks: HomesteadEngineCallbacks;
}

export class HomesteadEngine {
  public stage: Dungeon3DStage;
  public room: HomesteadRoom3D;
  public hero: Hero3D;
  public joystick: TouchJoystick;
  public damageText: DamageText3D;
  public passportStorage: SnekPassportStorage;
  public callbacks: HomesteadEngineCallbacks;

  public projectiles: Projectile3D[] = [];
  public activeStation: HomesteadStationSpec | null = null;
  public isModalOpen: boolean = false;

  private targetFireTimer: number = 0;
  private projectileIdCounter: number = 0;
  private resolvedProfile: ResolvedSnekCombatProfile;

  constructor(options: HomesteadEngineOptions) {
    this.callbacks = options.callbacks;
    this.passportStorage = options.passportStorage || new SnekPassportStorage();

    // 1. Stage
    this.stage = new Dungeon3DStage({
      container: options.container,
      onUpdate: (delta) => this.update(delta),
    });
    // Slightly warmer background for Homestead
    this.stage.scene.background = new THREE.Color(0x111827);

    // 2. Homestead Room
    this.room = new HomesteadRoom3D(this.stage.scene);

    // 3. Hero inside the Indoor Living Room (x=0, z=-3.2)
    this.hero = new Hero3D(this.stage.scene);
    this.hero.setPosition(0, -3.2);
    this.stage.follow(0, -3.2, 1.0);

    // 4. Joystick
    this.joystick = new TouchJoystick();
    this.joystick.attach(options.container);

    // 5. Damage Text for Target Dummy practice
    this.damageText = new DamageText3D(options.overlayContainer, this.stage.camera);

    // 6. Initial sync from localStorage passport
    const passport = this.passportStorage.load();
    this.resolvedProfile = ArtisanForgeService.resolveCombatStats(passport);
    this.syncFromPassport(passport.moodEmote || 'happy');
  }

  /**
   * 從 localStorage 重讀護照並即時更新 Snek 五維、頭頂 3D 念力武器模型與心情氣泡
   */
  public syncFromPassport(emote?: SnekEmoteType): void {
    const passport = this.passportStorage.load();
    this.resolvedProfile = ArtisanForgeService.resolveCombatStats(passport);

    this.hero.applyResolvedCombatProfile(this.resolvedProfile);
    this.hero.stats.hp = this.hero.stats.maxHp;
    this.hero.weaponMount.loadWeaponModel(this.resolvedProfile.weapon.modelUrl);

    if (emote) {
      this.hero.showEmote(emote, 1.8);
    }

    this.callbacks.onPassportSync(passport, this.resolvedProfile);
  }

  private update(delta: number): void {
    const heroPos = this.hero.getPosition();

    // 1. Move hero if modal is not blocking
    if (!this.isModalOpen) {
      const vec = this.joystick.getVector();
      const isMoving = this.joystick.isMoving();

      if (isMoving) {
        const moveDist = this.hero.stats.moveSpeed * delta;
        const clamped = this.room.clampPosition(
          heroPos.x + vec.x * moveDist,
          heroPos.z + vec.y * moveDist,
          heroPos.x,
          heroPos.z
        );
        this.hero.setPosition(clamped.x, clamped.z);
        this.hero.move(vec.x, vec.y, delta);
      } else {
        this.hero.move(0, 0, delta);
      }
    } else {
      this.hero.move(0, 0, delta);
    }

    // 2. Check active station proximity
    const currentPos = this.hero.getPosition();
    const station = this.room.update(delta, currentPos.x, currentPos.z);

    if (station?.id !== this.activeStation?.id) {
      this.activeStation = station;
      this.callbacks.onStationChange(station);

      if (station?.id === 'COZY_BED') {
        this.hero.heal(this.hero.stats.maxHp);
      } else if (station?.id === 'PORTAL_TERMINAL') {
        this.hero.showEmote('idea', 1.4);
      }
    }

    // 3. Target Practice Dummy Auto-Fire when standing in PRACTICE_TARGET zone
    if (station?.id === 'PRACTICE_TARGET' && !this.isModalOpen) {
      this.handleTargetPracticeFire(delta, currentPos.x, currentPos.z);
    }

    // 4. Update practice projectiles
    this.updatePracticeProjectiles(delta);

    // 5. Update Hero & Camera & Floating Text
    this.hero.update(delta);
    this.stage.follow(currentPos.x, currentPos.z, delta);
    this.damageText.update(delta);
  }

  private handleTargetPracticeFire(delta: number, heroX: number, heroZ: number): void {
    const dummyPos = this.room.getTargetDummyPosition();
    this.hero.faceTarget(dummyPos.x, dummyPos.z);

    this.targetFireTimer -= delta;
    if (this.targetFireTimer > 0) return;

    const rate = Math.max(0.5, this.resolvedProfile.attackSpeed);
    this.targetFireTimer = 1.0 / rate;
    this.hero.swingWeapon();

    const muzzleX = heroX + TELEKINETIC_MUZZLE_OFFSET.x;
    const muzzleZ = heroZ + TELEKINETIC_MUZZLE_OFFSET.z;
    const dx = dummyPos.x - muzzleX;
    const dz = dummyPos.z - muzzleZ;
    if (Math.hypot(dx, dz) <= 0.05) return;

    const baseAngle = Math.atan2(dx, dz);
    const shotCount = this.resolvedProfile.shotCount;
    const spreadAngle = this.resolvedProfile.spreadAngle;

    const isCrit = Math.random() < this.resolvedProfile.critChance;
    const dmg = Math.round(
      this.resolvedProfile.stats.atk * (isCrit ? this.resolvedProfile.critMultiplier : 1.0)
    );

    for (let s = 0; s < shotCount; s++) {
      const offsetIndex = shotCount > 1 ? s - (shotCount - 1) / 2 : 0;
      const angle = baseAngle + offsetIndex * (spreadAngle / Math.max(1, shotCount - 1));
      const vx = Math.sin(angle);
      const vz = Math.cos(angle);

      this.projectileIdCounter++;
      this.projectiles.push(
        new Projectile3D(this.stage.scene, {
          id: `home_proj_${this.projectileIdCounter}`,
          x: muzzleX + vx * 0.35,
          z: muzzleZ + vz * 0.35,
          vx,
          vz,
          damage: dmg,
          isCrit,
          life: 0.75,
          maxLife: 0.75,
          modelUrl: isCrit
            ? './assets/dungeon3d/kenney/blaster-kit/grenade-a.glb'
            : this.resolvedProfile.weapon.projectileModelUrl,
        })
      );
    }
  }

  private updatePracticeProjectiles(delta: number): void {
    const dummyPos = this.room.getTargetDummyPosition();
    const remaining: Projectile3D[] = [];

    for (let i = 0; i < this.projectiles.length; i++) {
      const proj = this.projectiles[i];
      proj.update(delta);

      if (proj.isExpired) {
        proj.destroy();
        this.stage.scene.remove(proj.group);
        continue;
      }

      const pPos = proj.getPosition();
      const dist = Math.hypot(pPos.x - dummyPos.x, pPos.z - dummyPos.z);

      if (dist < 0.95) {
        this.room.triggerTargetHit();
        const label = proj.config.isCrit
          ? `CRIT! -${proj.config.damage}`
          : `-${proj.config.damage}`;
        this.damageText.spawn(
          dummyPos.x + (Math.random() - 0.5) * 0.4,
          1.55,
          dummyPos.z,
          label,
          proj.config.isCrit ? 'crit' : 'damage'
        );
        proj.destroy();
        this.stage.scene.remove(proj.group);
      } else {
        remaining.push(proj);
      }
    }

    this.projectiles = remaining;
  }

  public destroy(): void {
    for (let i = 0; i < this.projectiles.length; i++) {
      this.projectiles[i].destroy();
      this.stage.scene.remove(this.projectiles[i].group);
    }
    this.projectiles = [];
    this.hero.destroy();
    this.stage.scene.remove(this.hero.group);
    this.room.destroy();
    this.stage.scene.remove(this.room.group);
    this.damageText.destroy();
    this.joystick.destroy();
    this.stage.destroy();
  }
}
