import { ISkillCard, SkillCardContext } from '../ISkillCard.ts';

export class CompoundInterestCard implements ISkillCard {
  public readonly id = 'COMPOUND_INTEREST';
  public readonly title = '第八奇蹟複利雪球';
  public readonly badge = '指數收益';
  public readonly category = 'SPECIAL';
  public readonly iconKey = 'growth';
  public readonly maxLevel = 8;
  public readonly financeTerm = '【複利 (Compound Interest)】將獲得收益持續再投資，隨時間產生驚人的指數級增長。';

  public getDescription(currentLevel: number): string {
    const next = currentLevel + 1;
    const killsRequired = Math.max(8, 16 - next);
    return `每平倉 ${killsRequired} 隻怪獸永久增傷 +3%，最大增傷上限提高至 ${(1.5 + next * 0.2).toFixed(1)}x`;
  }

  public isEligible(context: SkillCardContext): boolean {
    const current = context.engine.skillLevels?.get(this.id) ?? 0;
    return current < this.maxLevel;
  }

  public apply(context: SkillCardContext, nextLevel: number): void {
    context.engine.hasCompoundInterest = true;
    context.engine.compoundKillsThreshold = Math.max(8, 16 - nextLevel);
    context.engine.compoundMaxMultiplier = 1.5 + nextLevel * 0.2;
    context.engine.damageMultiplier = (context.engine.damageMultiplier || 1.0) * 1.08;
  }
}
