import * as THREE from 'three';
import { GLTFModelLoader } from '../core/GLTFModelLoader.ts';

export class LootChest3D {
  public group: THREE.Group;
  public isOpened: boolean = false;
  public isReady: boolean = false;

  private lidGroup: THREE.Group;
  private fallbackGroup: THREE.Group;
  private glbCrate: THREE.Object3D | null = null;
  private glowRing: THREE.Mesh;
  private goldAwarded: number = 0;
  private openProgress: number = 0;
  private fallY: number = 6.0;

  constructor(scene: THREE.Scene, posX: number, posZ: number, gold: number = 50) {
    this.goldAwarded = gold;
    this.group = new THREE.Group();
    scene.add(this.group);
    this.group.position.set(posX, this.fallY, posZ);

    // Golden ground beacon ring
    const ringGeo = new THREE.RingGeometry(0.65, 0.9, 24);
    const ringMat = new THREE.MeshBasicMaterial({
      color: 0xffd700,
      transparent: true,
      opacity: 0.7,
      side: THREE.DoubleSide,
      depthWrite: false,
    });
    this.glowRing = new THREE.Mesh(ringGeo, ringMat);
    this.glowRing.rotation.x = -Math.PI / 2;
    this.glowRing.position.y = 0.03;
    this.group.add(this.glowRing);

    this.fallbackGroup = new THREE.Group();
    this.group.add(this.fallbackGroup);

    // 1. Chest Base (Fallback)
    const baseGeo = new THREE.BoxGeometry(1.0, 0.5, 0.7);
    const baseMat = new THREE.MeshStandardMaterial({
      color: 0x8b5a2b,
      roughness: 0.6,
      metalness: 0.2,
    });
    const baseMesh = new THREE.Mesh(baseGeo, baseMat);
    baseMesh.position.y = 0.25;
    this.fallbackGroup.add(baseMesh);

    const trimGeo = new THREE.BoxGeometry(1.04, 0.1, 0.74);
    const goldMat = new THREE.MeshStandardMaterial({
      color: 0xffd700,
      roughness: 0.2,
      metalness: 0.9,
      emissive: 0xffaa00,
      emissiveIntensity: 0.3,
    });
    const trimMesh = new THREE.Mesh(trimGeo, goldMat);
    trimMesh.position.y = 0.25;
    this.fallbackGroup.add(trimMesh);

    // 2. Chest Lid
    this.lidGroup = new THREE.Group();
    this.lidGroup.position.set(0, 0.5, -0.35);

    const lidGeo = new THREE.BoxGeometry(1.02, 0.25, 0.72);
    const lidMesh = new THREE.Mesh(lidGeo, baseMat);
    lidMesh.position.set(0, 0.125, 0.35);
    this.lidGroup.add(lidMesh);

    const lockGeo = new THREE.BoxGeometry(0.18, 0.2, 0.1);
    const lockMesh = new THREE.Mesh(lockGeo, goldMat);
    lockMesh.position.set(0, 0.1, 0.72);
    this.lidGroup.add(lockMesh);

    this.fallbackGroup.add(this.lidGroup);

    // Load Kenney Blaster Supply Crate GLB
    this.loadCrateGLB('./assets/dungeon3d/kenney/blaster-kit/crate-wide.glb');
  }

  private loadCrateGLB(url: string): void {
    GLTFModelLoader.getInstance()
      .load(url)
      .then((gltf) => {
        const { scene: model } = GLTFModelLoader.getInstance().instantiate(gltf);
        const box = new THREE.Box3().setFromObject(model);
        const size = new THREE.Vector3();
        const center = new THREE.Vector3();
        box.getSize(size);
        box.getCenter(center);

        const scale = 1.35 / Math.max(size.x, size.z, 0.01);
        model.scale.setScalar(scale);
        model.position.set(-center.x * scale, -box.min.y * scale, -center.z * scale);

        model.traverse((child) => {
          if (child instanceof THREE.Mesh && child.material) {
            const mat = child.material as THREE.MeshStandardMaterial;
            if (mat.map) {
              mat.map.colorSpace = THREE.SRGBColorSpace;
            }
          }
        });

        this.glbCrate = model;
        this.fallbackGroup.visible = false;
        this.group.add(model);
      })
      .catch(() => {
        // Keep fallback chest
      });
  }

  public update(delta: number, heroX: number, heroZ: number): { opened: boolean; gold: number; heal: number } {
    // Drop animation
    if (!this.isReady) {
      this.fallY = Math.max(0, this.fallY - delta * 18);
      this.group.position.y = this.fallY;
      if (this.fallY <= 0) {
        this.isReady = true;
      }
      return { opened: false, gold: 0, heal: 0 };
    }

    this.glowRing.rotation.z += delta * 1.5;

    // Approach trigger
    if (!this.isOpened) {
      const dx = heroX - this.group.position.x;
      const dz = heroZ - this.group.position.z;
      if (Math.hypot(dx, dz) < 1.6) {
        this.isOpened = true;
        return { opened: true, gold: this.goldAwarded, heal: 25 };
      }
    } else if (this.openProgress < 1.0) {
      // Smooth lid / crate pop animation
      this.openProgress = Math.min(1.0, this.openProgress + delta * 3.5);
      this.lidGroup.rotation.x = -this.openProgress * (Math.PI * 0.55);
      if (this.glbCrate) {
        const bounce = Math.sin(this.openProgress * Math.PI) * 0.35;
        this.glbCrate.position.y = bounce;
        this.glbCrate.rotation.y = this.openProgress * Math.PI * 0.25;
      }
    }

    return { opened: false, gold: 0, heal: 0 };
  }

  public destroy(): void {
    this.group.traverse((obj) => {
      if (obj instanceof THREE.Mesh) {
        obj.geometry?.dispose();
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material?.dispose();
        }
      }
    });
  }
}
