import {
  CURRENT_PASSPORT_SCHEMA_VERSION,
  DEFAULT_PASSPORT_STORAGE_KEY,
  PassportMigrator,
  SnekPetPassport,
} from '../types.ts';
import { SDK_WEAPON_TIERS, createWeaponFromTier } from '../catalogs/weaponsCatalog.ts';

export class SnekPassportStorage {
  private storageKey: string;
  private targetSchemaVersion: number;
  private migrators: Map<number, { toVersion: number; migrate: PassportMigrator }> = new Map();

  constructor(
    storageKey: string = DEFAULT_PASSPORT_STORAGE_KEY,
    targetSchemaVersion: number = CURRENT_PASSPORT_SCHEMA_VERSION
  ) {
    this.storageKey = storageKey;
    this.targetSchemaVersion = targetSchemaVersion;

    // 內建 v0 (無版號或早期舊格式) -> v1 的無損升版遷移器
    this.registerMigration(0, 1, (raw) => {
      const defaults = SnekPassportStorage.createDefaultPassport();
      const rawStats = raw.baseStats || raw.stats || {};
      return {
        ...defaults,
        ...raw,
        schemaVersion: 1,
        petId: raw.petId || defaults.petId,
        petName: raw.petName || defaults.petName,
        level: typeof raw.level === 'number' ? raw.level : defaults.level,
        exp: typeof raw.exp === 'number' ? raw.exp : defaults.exp,
        affection: typeof raw.affection === 'number' ? raw.affection : defaults.affection,
        moodEmote: raw.moodEmote || defaults.moodEmote,
        baseStats: {
          hp: typeof rawStats.hp === 'number' ? rawStats.hp : defaults.baseStats.hp,
          atk: typeof rawStats.atk === 'number' ? rawStats.atk : defaults.baseStats.atk,
          def: typeof rawStats.def === 'number' ? rawStats.def : defaults.baseStats.def,
          speed:
            typeof rawStats.speed === 'number'
              ? rawStats.speed
              : typeof rawStats.moveSpeed === 'number'
                ? rawStats.moveSpeed
                : defaults.baseStats.speed,
          luck: typeof rawStats.luck === 'number' ? rawStats.luck : defaults.baseStats.luck,
        },
        equippedWeapon: raw.equippedWeapon
          ? {
              ...defaults.equippedWeapon,
              ...raw.equippedWeapon,
              iconUrl:
                typeof raw.equippedWeapon.iconUrl === 'string' &&
                raw.equippedWeapon.iconUrl.includes('/kenney/')
                  ? raw.equippedWeapon.iconUrl
                  : SDK_WEAPON_TIERS[
                      Math.max(0, Math.min(SDK_WEAPON_TIERS.length - 1, (raw.equippedWeapon.tier || 1) - 1))
                    ].iconUrl,
              modelUrl:
                typeof raw.equippedWeapon.modelUrl === 'string' &&
                raw.equippedWeapon.modelUrl.includes('/kenney/')
                  ? raw.equippedWeapon.modelUrl
                  : SDK_WEAPON_TIERS[
                      Math.max(0, Math.min(SDK_WEAPON_TIERS.length - 1, (raw.equippedWeapon.tier || 1) - 1))
                    ].modelUrl,
              enchantmentTags: Array.isArray(raw.equippedWeapon.enchantmentTags)
                ? [...raw.equippedWeapon.enchantmentTags]
                : [],
            }
          : defaults.equippedWeapon,
        wallet: {
          gold:
            typeof raw.wallet?.gold === 'number'
              ? raw.wallet.gold
              : typeof raw.gold === 'number'
                ? raw.gold
                : defaults.wallet.gold,
        },
        inventory:
          raw.inventory && typeof raw.inventory === 'object' ? { ...raw.inventory } : {},
        backpackCapacity:
          typeof raw.backpackCapacity === 'number' && raw.backpackCapacity > 0
            ? raw.backpackCapacity
            : defaults.backpackCapacity,
        stash: raw.stash && typeof raw.stash === 'object' ? { ...raw.stash } : {},
        unlockedWeapons: Array.isArray(raw.unlockedWeapons)
          ? [...raw.unlockedWeapons]
          : defaults.unlockedWeapons,
        unlockedEnchantments: Array.isArray(raw.unlockedEnchantments)
          ? [...raw.unlockedEnchantments]
          : defaults.unlockedEnchantments,
        worldProgress:
          raw.worldProgress && typeof raw.worldProgress === 'object'
            ? { ...raw.worldProgress }
            : {},
      };
    });
  }

  /**
   * 建立全新初始 v1 Snek 專屬寵物護照
   */
  public static createDefaultPassport(petName: string = '專屬小蛇 SNEK'): SnekPetPassport {
    return {
      schemaVersion: CURRENT_PASSPORT_SCHEMA_VERSION,
      petId: 'snek_pet_main',
      petName,
      updatedAt: Date.now(),
      level: 1,
      exp: 0,
      affection: 60,
      moodEmote: 'happy',
      baseStats: {
        hp: 100,
        atk: 25,
        def: 5,
        speed: 6.5,
        luck: 20, // 20% 基礎暴擊率
      },
      equippedWeapon: createWeaponFromTier(0, 0, []),
      wallet: {
        gold: 0,
      },
      inventory: {},
      backpackCapacity: 9,
      stash: {},
      unlockedWeapons: ['blaster_tier_1'],
      unlockedEnchantments: [],
      worldProgress: {},
    };
  }

  /**
   * 註冊版本升版遷移器 (例如 1 -> 2, 2 -> 3)
   */
  public registerMigration(
    fromVersion: number,
    toVersion: number,
    migrate: PassportMigrator
  ): void {
    if (toVersion <= fromVersion) {
      throw new Error(`Invalid migration version range: ${fromVersion} -> ${toVersion}`);
    }
    this.migrators.set(fromVersion, { toVersion, migrate });
  }

  /**
   * 從 localStorage 載入護照；若版本較舊則自動鏈式升版並回存，若不存在或損毀則初始化預設護照
   */
  public load(): SnekPetPassport {
    try {
      const rawJson = window.localStorage.getItem(this.storageKey);
      if (!rawJson) {
        const fresh = SnekPassportStorage.createDefaultPassport();
        this.save(fresh);
        return fresh;
      }

      const parsed = JSON.parse(rawJson);
      if (!parsed || typeof parsed !== 'object') {
        const fallback = SnekPassportStorage.createDefaultPassport();
        this.save(fallback);
        return fallback;
      }

      const migrated = this.migrateIfNeeded(parsed);
      return migrated;
    } catch {
      const fallback = SnekPassportStorage.createDefaultPassport();
      this.save(fallback);
      return fallback;
    }
  }

  /**
   * 將護照儲存至 localStorage（強制確保 schemaVersion 與 updatedAt）
   */
  public save(passport: SnekPetPassport): SnekPetPassport {
    const normalized: SnekPetPassport = {
      ...passport,
      schemaVersion: this.targetSchemaVersion,
      updatedAt: Date.now(),
    };
    try {
      window.localStorage.setItem(this.storageKey, JSON.stringify(normalized));
    } catch {
      // Ignore quota errors in restricted environments
    }
    return normalized;
  }

  /**
   * 重置護照回預設狀態
   */
  public reset(petName?: string): SnekPetPassport {
    const fresh = SnekPassportStorage.createDefaultPassport(petName);
    return this.save(fresh);
  }

  /**
   * 執行鏈式版本升版遷移 (v0 -> v1 -> v2 ...)
   */
  public migrateIfNeeded(raw: Record<string, any>): SnekPetPassport {
    let currentVersion = typeof raw.schemaVersion === 'number' ? raw.schemaVersion : 0;
    let currentData: Record<string, any> = { ...raw };
    let didMigrate = false;
    let safetySteps = 0;

    while (currentVersion < this.targetSchemaVersion && safetySteps < 20) {
      safetySteps++;
      const step = this.migrators.get(currentVersion);
      if (!step) {
        // 若中間未定義自訂遷移器，則以 v0->v1 正規化補齊預設欄位並推進至目標版本
        const fallbackMigrator = this.migrators.get(0);
        if (fallbackMigrator) {
          currentData = fallbackMigrator.migrate(currentData);
        }
        currentData.schemaVersion = this.targetSchemaVersion;
        currentVersion = this.targetSchemaVersion;
        didMigrate = true;
        break;
      }

      currentData = step.migrate(currentData);
      currentData.schemaVersion = step.toVersion;
      currentVersion = step.toVersion;
      didMigrate = true;
    }

    // 確保基本五維與必要結構齊全
    const baseChecker = this.migrators.get(0);
    if (baseChecker) {
      const sanitized = baseChecker.migrate(currentData);
      sanitized.schemaVersion = currentVersion;
      currentData = sanitized;
    }

    const result = currentData as SnekPetPassport;
    if (didMigrate) {
      this.save(result);
    }
    return result;
  }
}
