import {
  ENCHANTMENT_CATALOG,
  createWeaponFromTier,
} from '../catalogs/weaponsCatalog.ts';
import {
  ResolvedSnekCombatProfile,
  SnekCoreStats,
  SnekPetPassport,
  WeaponEnchantmentTag,
} from '../types.ts';

export const MAX_WEAPON_UPGRADE_LEVEL = 10;
export const MAX_ENCHANTMENT_SLOTS = 3;

export class ArtisanForgeService {
  /**
   * 計算武器從 +N 強化至 +(N+1) 所需的金幣費用
   */
  public static getUpgradeGoldCost(currentUpgradeLevel: number): number {
    return 40 + currentUpgradeLevel * 35;
  }

  /**
   * 結合「寵物本體五維 + 武器基礎加成 + 工匠強化 (+0~+10) + 附魔標籤 + 親密度」算出最終面板
   */
  public static resolveCombatStats(passport: SnekPetPassport): ResolvedSnekCombatProfile {
    const base = passport.baseStats;
    const weapon = passport.equippedWeapon;
    const bonus = weapon.bonusStats || {};
    const upgradeLv = Math.max(0, Math.min(MAX_WEAPON_UPGRADE_LEVEL, weapon.upgradeLevel || 0));
    const tags = new Set<WeaponEnchantmentTag>(weapon.enchantmentTags || []);

    // 親密度大於 75 時提供 5% 全能力加成
    const affectionMul = passport.affection >= 75 ? 1.05 : 1.0;

    // 工匠每 +1 級提升 +4 ATK、+2% 攻速
    let hp = Math.round((base.hp + (bonus.hp || 0) + (passport.level - 1) * 8) * affectionMul);
    let atk = Math.round(
      (base.atk + (bonus.atk || 0) + upgradeLv * 4 + (passport.level - 1) * 3) * affectionMul
    );
    let def = Math.round((base.def + (bonus.def || 0) + Math.floor(upgradeLv / 3)) * affectionMul);
    let speed = Number(((base.speed + (bonus.speed || 0)) * affectionMul).toFixed(2));
    let luck = Math.round((base.luck + (bonus.luck || 0)) * affectionMul);

    let attackSpeedMultiplier = weapon.attackSpeedMultiplier * (1 + upgradeLv * 0.02);
    let shotCount = weapon.shotCount ?? 1;
    let spreadAngle = weapon.spreadAngle ?? 0;
    let pierceCount = weapon.pierceCount ?? 0;
    let explosionRadius = weapon.explosionRadius ?? 0;
    let critMultiplier = 1.8;
    let vampiricHealOnKill = 0;
    let frostSlowRatio = 0;

    // 套用武器附魔標籤加成
    if (tags.has('MULTI_SHOT')) {
      shotCount += 1;
      spreadAngle = Math.max(0.14, spreadAngle + 0.1);
    }
    if (tags.has('PIERCE')) {
      pierceCount += 1;
    }
    if (tags.has('EXPLOSIVE')) {
      explosionRadius = explosionRadius > 0 ? explosionRadius + 0.8 : 1.8;
    }
    if (tags.has('FROST_BITE')) {
      atk += 6;
      frostSlowRatio = 0.25;
    }
    if (tags.has('VAMPIRIC')) {
      vampiricHealOnKill = 4;
    }
    if (tags.has('CRIT_BOOST')) {
      luck += 12;
      critMultiplier += 0.35;
    }
    if (tags.has('HASTE')) {
      attackSpeedMultiplier *= 1.18;
      speed = Number((speed + 0.4).toFixed(2));
    }

    const critChance = Math.min(0.85, Math.max(0.05, luck / 100));
    const baseAttackRate = 2.0; // 每秒基礎攻擊 2 次
    const attackSpeed = Number((baseAttackRate * attackSpeedMultiplier).toFixed(2));

    const resolvedStats: SnekCoreStats = {
      hp,
      atk,
      def,
      speed,
      luck,
    };

    return {
      stats: resolvedStats,
      critChance,
      critMultiplier: Number(critMultiplier.toFixed(2)),
      attackSpeed,
      shotCount,
      spreadAngle: Number(spreadAngle.toFixed(3)),
      pierceCount,
      explosionRadius: Number(explosionRadius.toFixed(2)),
      vampiricHealOnKill,
      frostSlowRatio,
      enchantmentTags: Array.from(tags),
      weapon: {
        ...weapon,
        enchantmentTags: Array.from(tags),
      },
    };
  }

  /**
   * 工匠強化：消耗金幣將當前念力武器強化 +1 (最高 +10)
   */
  public static upgradeWeapon(passport: SnekPetPassport): {
    success: boolean;
    passport: SnekPetPassport;
    cost: number;
    reason?: string;
  } {
    const currentLv = passport.equippedWeapon.upgradeLevel || 0;
    if (currentLv >= MAX_WEAPON_UPGRADE_LEVEL) {
      return {
        success: false,
        passport,
        cost: 0,
        reason: 'MAX_LEVEL_REACHED',
      };
    }

    const cost = ArtisanForgeService.getUpgradeGoldCost(currentLv);
    if (passport.wallet.gold < cost) {
      return {
        success: false,
        passport,
        cost,
        reason: 'INSUFFICIENT_GOLD',
      };
    }

    const updated: SnekPetPassport = {
      ...passport,
      moodEmote: 'star',
      wallet: {
        ...passport.wallet,
        gold: passport.wallet.gold - cost,
      },
      equippedWeapon: {
        ...passport.equippedWeapon,
        upgradeLevel: currentLv + 1,
      },
    };

    return {
      success: true,
      passport: updated,
      cost,
    };
  }

  /**
   * 武器階級進化：將念力武器進化至指定階級 (0..5)，並完整保留既有的工匠強化等級 (+N) 與附魔標籤
   */
  public static evolveWeaponTier(
    passport: SnekPetPassport,
    targetTierIndex: number
  ): SnekPetPassport {
    const prevWeapon = passport.equippedWeapon;
    const nextWeapon = createWeaponFromTier(
      targetTierIndex,
      prevWeapon.upgradeLevel,
      prevWeapon.enchantmentTags
    );

    return {
      ...passport,
      moodEmote: 'stars',
      equippedWeapon: nextWeapon,
    };
  }

  /**
   * 工匠附魔：為武器鑲嵌附魔標籤（最多 3 槽）
   */
  public static addEnchantment(
    passport: SnekPetPassport,
    tag: WeaponEnchantmentTag,
    consumeResources: boolean = false
  ): {
    success: boolean;
    passport: SnekPetPassport;
    reason?: string;
  } {
    const existing = passport.equippedWeapon.enchantmentTags || [];
    if (existing.includes(tag)) {
      return {
        success: false,
        passport,
        reason: 'ALREADY_ENCHANTED',
      };
    }
    if (existing.length >= MAX_ENCHANTMENT_SLOTS) {
      return {
        success: false,
        passport,
        reason: 'SLOTS_FULL',
      };
    }

    let nextPassport: SnekPetPassport = {
      ...passport,
      inventory: { ...passport.inventory },
      stash: { ...(passport.stash || {}) },
    };

    if (consumeResources) {
      const entry = ENCHANTMENT_CATALOG[tag];
      if (nextPassport.wallet.gold < entry.goldCost) {
        return {
          success: false,
          passport,
          reason: 'INSUFFICIENT_GOLD',
        };
      }
      const haveInBag = nextPassport.inventory[entry.materialId] || 0;
      const haveInStash = nextPassport.stash?.[entry.materialId] || 0;
      const haveMat = haveInBag + haveInStash;
      if (haveMat < entry.materialCount) {
        return {
          success: false,
          passport,
          reason: 'INSUFFICIENT_MATERIAL',
        };
      }

      nextPassport.wallet = {
        ...nextPassport.wallet,
        gold: nextPassport.wallet.gold - entry.goldCost,
      };

      let toDeduct = entry.materialCount;
      const fromStash = Math.min(haveInStash, toDeduct);
      if (fromStash > 0 && nextPassport.stash) {
        nextPassport.stash[entry.materialId] = haveInStash - fromStash;
        if (nextPassport.stash[entry.materialId] <= 0) {
          delete nextPassport.stash[entry.materialId];
        }
        toDeduct -= fromStash;
      }
      if (toDeduct > 0) {
        nextPassport.inventory[entry.materialId] = haveInBag - toDeduct;
        if (nextPassport.inventory[entry.materialId] <= 0) {
          delete nextPassport.inventory[entry.materialId];
        }
      }
    }

    const updated: SnekPetPassport = {
      ...nextPassport,
      moodEmote: 'hearts',
      equippedWeapon: {
        ...nextPassport.equippedWeapon,
        enchantmentTags: [...existing, tag],
      },
    };

    return {
      success: true,
      passport: updated,
    };
  }

  /**
   * 餵食寵物料理：提升親密度與永久或當局基礎五維
   */
  public static feedPet(
    passport: SnekPetPassport,
    affectionGain: number,
    statBonus?: Partial<SnekCoreStats>
  ): SnekPetPassport {
    return {
      ...passport,
      affection: Math.min(100, Math.max(0, passport.affection + affectionGain)),
      moodEmote: 'heart',
      baseStats: {
        hp: passport.baseStats.hp + (statBonus?.hp || 0),
        atk: passport.baseStats.atk + (statBonus?.atk || 0),
        def: passport.baseStats.def + (statBonus?.def || 0),
        speed: Number((passport.baseStats.speed + (statBonus?.speed || 0)).toFixed(2)),
        luck: passport.baseStats.luck + (statBonus?.luck || 0),
      },
    };
  }
}
