import { Dungeon3DView } from './games/dungeon3d/Dungeon3DView.ts';
import { MoonRunView } from './games/moonrun/MoonRunView.ts';
import { SnakeView } from './games/snake/SnakeView.ts';
import { SurvivorView } from './games/survivor/SurvivorView.ts';
import { LobbyView } from './views/LobbyView.ts';
import { SnekPetHomeView } from './views/SnekPetHomeView.ts';
import { AnalyticsService } from './platform/AnalyticsService.ts';

export class Router {
  private appContainer: HTMLElement;
  private currentCleanup: (() => void) | null = null;

  constructor(appContainer: HTMLElement) {
    this.appContainer = appContainer;
    window.addEventListener('hashchange', () => this.handleRoute());
  }

  public init(): void {
    if (!window.location.hash) {
      const pathname = (window.location.pathname || '').toLowerCase();
      if (pathname.includes('survivor')) {
        window.location.hash = '#/game/survivor' + (window.location.search || '');
      } else {
        window.location.hash = '#/';
      }
    }
    this.handleRoute();
  }

  public navigate(hash: string): void {
    window.location.hash = hash;
  }

  private async handleRoute(): Promise<void> {
    const rawHash = (window.location.hash.slice(1) || '/').split('?')[0];
    const path = rawHash.startsWith('/') ? rawHash : `/${rawHash}`;

    // Clean up previous view
    if (this.currentCleanup) {
      this.currentCleanup();
      this.currentCleanup = null;
    }

    let pageTitle = '遊戲大廳';
    if (path === '/' || path === '/lobby') {
      pageTitle = '街機遊戲大廳';
      const lobby = new LobbyView(this.appContainer);
      this.currentCleanup = await lobby.mount();
    } else if (path === '/pet' || window.location.hash.includes('beam=')) {
      pageTitle = 'Snek 寵物家園';
      const petHome = new SnekPetHomeView(this.appContainer);
      this.currentCleanup = petHome.mount();
    } else if (path === '/game/snake') {
      pageTitle = 'SNEK Classic 貪食蛇';
      const snake = new SnakeView(this.appContainer);
      this.currentCleanup = snake.mount();
    } else if (path === '/game/survivor' || path === '/survivor') {
      pageTitle = 'SNEK Survivor 蛇蛇倖存者';
      const survivor = new SurvivorView(this.appContainer);
      this.currentCleanup = survivor.mount();
    } else if (path === '/game/moonrun') {
      pageTitle = 'SNEK Moon Run 登月衝天';
      const moonrun = new MoonRunView(this.appContainer);
      this.currentCleanup = moonrun.mount();
    } else if (path === '/game/merge' || path === '/merge') {
      // SNEK Merge is a standalone full-screen page (dist/merge/), not an SPA view
      const query = window.location.hash.includes('?') ? `?${window.location.hash.split('?')[1]}` : window.location.search;
      window.location.href = `./merge/${query}`;
      return;
    } else if (path === '/game/dungeon3d' || path === '/dungeon3d') {
      pageTitle = 'SNEK 3D 地下城';
      const dungeon3d = new Dungeon3DView(this.appContainer);
      this.currentCleanup = dungeon3d.mount();
    } else {
      // Fallback
      window.location.hash = '#/';
      return;
    }

    AnalyticsService.trackPageView(path, pageTitle);
  }
}
