import * as THREE from 'three';
import { ProjectileConfig } from '../types.ts';
import { GLTFModelLoader } from '../core/GLTFModelLoader.ts';

export class Projectile3D {
  public group: THREE.Group;
  public config: ProjectileConfig;
  public isExpired: boolean = false;
  public radius: number = 0.45;
  public pierceLeft: number = 0;
  public explosionRadius: number = 0;
  public hitMonsterIds: Set<string> = new Set();

  private mesh: THREE.Mesh;
  private glowMesh: THREE.Mesh;
  private modelHolder: THREE.Group;

  constructor(scene: THREE.Scene, config: ProjectileConfig) {
    this.config = { ...config };
    this.pierceLeft = config.pierceLeft ?? 0;
    this.explosionRadius = config.explosionRadius ?? 0;

    this.group = new THREE.Group();
    scene.add(this.group);
    this.group.position.set(config.x, 0.72, config.z);

    this.modelHolder = new THREE.Group();
    this.group.add(this.modelHolder);

    // Fallback core energy bolt
    const bladeGeo = new THREE.BoxGeometry(0.35, 0.14, 0.55);
    const bladeMat = new THREE.MeshBasicMaterial({
      color: config.isCrit ? 0xffeb3b : 0x00ffff,
    });
    this.mesh = new THREE.Mesh(bladeGeo, bladeMat);
    this.modelHolder.add(this.mesh);

    // Glowing outer aura trail
    const glowGeo = new THREE.SphereGeometry(config.isCrit ? 0.28 : 0.2, 8, 8);
    const glowMat = new THREE.MeshBasicMaterial({
      color: config.isCrit ? 0xff9800 : 0x00e676,
      transparent: true,
      opacity: 0.42,
    });
    this.glowMesh = new THREE.Mesh(glowGeo, glowMat);
    this.group.add(this.glowMesh);

    // Align rotation with velocity
    const angle = Math.atan2(config.vx, config.vz);
    this.group.rotation.y = angle;

    // Load Kenney 3D Bullet or Grenade model
    const bulletUrl =
      config.modelUrl ||
      (config.isCrit
        ? './assets/dungeon3d/kenney/blaster-kit/grenade-a.glb'
        : './assets/dungeon3d/kenney/blaster-kit/bullet-foam-tip-thick.glb');
    this.loadBulletGLB(bulletUrl);
  }

  private loadBulletGLB(url: string): void {
    GLTFModelLoader.getInstance()
      .load(url)
      .then((gltf) => {
        if (this.isExpired) return;
        const { scene: model } = GLTFModelLoader.getInstance().instantiate(gltf);

        const box = new THREE.Box3().setFromObject(model);
        const size = new THREE.Vector3();
        box.getSize(size);
        const maxDim = Math.max(size.x, size.y, size.z, 0.005);
        const targetSize = this.config.isCrit ? 0.55 : 0.48;
        const scale = targetSize / maxDim;
        model.scale.setScalar(scale);
        // Rotate foam dart (+Y up in GLB) so tip points forward along +Z
        model.rotation.x = Math.PI / 2;

        this.mesh.visible = false;
        this.modelHolder.add(model);
      })
      .catch(() => {
        // Keep fallback energy bolt
      });
  }

  public update(delta: number): void {
    if (this.isExpired) return;

    this.config.life -= delta;
    if (this.config.life <= 0) {
      this.isExpired = true;
      return;
    }

    const speed = 18.0;
    this.group.position.x += this.config.vx * speed * delta;
    this.group.position.z += this.config.vz * speed * delta;

    // Spin projectile around its forward flight axis (+Z)
    this.modelHolder.rotation.z += delta * 16;
  }

  public getPosition(): THREE.Vector3 {
    return this.group.position;
  }

  public destroy(): void {
    this.group.traverse((obj) => {
      if (obj instanceof THREE.Mesh) {
        obj.geometry?.dispose();
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material?.dispose();
        }
      }
    });
  }
}
