import { IBalanceRule } from '../IBalanceRule.ts';
import { PacingMetrics, PacingModifiers, PacingState } from '../types.ts';

/**
 * PinchRescueRule (危機守護規則)
 * When player HP drops below 20%, subtly boosts battlefield heart drop chance
 * to enable clutch comebacks and thrilling near-death moments.
 */
export class PinchRescueRule implements IBalanceRule {
  public readonly id = 'PINCH_RESCUE_RULE';

  public evaluate(
    metrics: PacingMetrics,
    modifiers: PacingModifiers,
    currentState: PacingState
  ): PacingState | void {
    if (metrics.playerHpRatio > 0 && metrics.playerHpRatio <= 0.20) {
      modifiers.heartDropBonusRate = Math.max(modifiers.heartDropBonusRate, 0.25);
      return 'PINCH_RESCUE';
    }
    return currentState;
  }
}
