import * as THREE from 'three';
import {
  ArtisanForgeService,
  ITEM_CATALOG,
  SnekInventoryService,
  SnekPassportStorage,
  SnekPortalHost,
  SnekStatsContainer,
} from '../../sdk/snek-pet/index.ts';
import { Dungeon3DStage } from './core/Dungeon3DStage.ts';
import { TouchJoystick } from './core/TouchJoystick.ts';
import { DungeonRoom } from './dungeon/DungeonRoom.ts';
import { DamageText3D } from './entities/DamageText3D.ts';
import { FOOD_CATALOG, FoodDrop3D } from './entities/FoodDrop3D.ts';
import { Hero3D } from './entities/Hero3D.ts';
import { LootChest3D } from './entities/LootChest3D.ts';
import { Monster3D } from './entities/Monster3D.ts';
import { Projectile3D } from './entities/Projectile3D.ts';
import { CollisionSystem, ProjectileHitEvent } from './systems/CollisionSystem.ts';
import { CombatSystem } from './systems/CombatSystem.ts';
import { FloorDirector } from './systems/FloorDirector.ts';
import { DungeonCallbacks } from './types.ts';

export interface DungeonEngineOptions {
  container: HTMLElement;
  overlayContainer: HTMLElement;
  callbacks: DungeonCallbacks;
  passportStorage?: SnekPassportStorage;
}

export class Dungeon3DEngine {
  public stage: Dungeon3DStage;
  public joystick: TouchJoystick;
  public room: DungeonRoom;
  public hero: Hero3D;
  public monsters: Monster3D[] = [];
  public projectiles: Projectile3D[] = [];
  public foodDrops: FoodDrop3D[] = [];
  public chest: LootChest3D | null = null;
  public damageText: DamageText3D;
  public callbacks: DungeonCallbacks;

  public combatSystem: CombatSystem;
  public passportStorage: SnekPassportStorage;
  public portalHost: SnekPortalHost;

  public floor: number = 1;
  public isRoomCleared: boolean = false;
  public isGameOver: boolean = false;
  public isPaused: boolean = false;

  private foodIdCounter: number = 0;
  private runGoldEarned: number = 0;

  constructor(options: DungeonEngineOptions) {
    this.callbacks = options.callbacks;
    this.passportStorage = options.passportStorage || new SnekPassportStorage();
    this.portalHost = new SnekPortalHost({ storage: this.passportStorage });
    this.combatSystem = new CombatSystem(12.0);

    // 1. Stage & Loop
    this.stage = new Dungeon3DStage({
      container: options.container,
      onUpdate: (delta) => this.update(delta),
    });

    // 2. Room
    this.room = new DungeonRoom(this.stage.scene);

    // 3. Hero (8-directional Snek + upper-right telekinetic weapon + emote bubble)
    this.hero = new Hero3D(this.stage.scene);

    // Sync initial five core stats from SnekPetPassport
    const passport = this.passportStorage.load();
    const resolvedProfile = ArtisanForgeService.resolveCombatStats(passport);
    this.hero.applyResolvedCombatProfile(resolvedProfile);
    this.hero.stats.hp = this.hero.stats.maxHp;

    // 4. Joystick
    this.joystick = new TouchJoystick();
    this.joystick.attach(options.container);

    // 5. Floating text
    this.damageText = new DamageText3D(options.overlayContainer, this.stage.camera);

    // Notify initial weapon
    this.callbacks.onWeaponChange?.(this.hero.getCurrentWeapon());

    // Start floor 1
    this.startFloor(1);
  }

  public startFloor(floorNumber: number): void {
    this.floor = floorNumber;
    this.hero.stats.floor = floorNumber;
    this.isRoomCleared = false;
    this.room.setPortalActive(false);

    // Auto-upgrade weapon every 2 floors if hero hasn't reached that tier yet
    const targetTierIdx = Math.min(5, Math.floor((floorNumber - 1) / 2));
    if ((this.hero.stats.weaponTier ?? 1) - 1 < targetTierIdx) {
      const upgraded = this.hero.setWeaponTier(targetTierIdx);
      this.callbacks.onWeaponChange?.(upgraded);
    }

    // Clean existing monsters, projectiles, food drops & chest
    this.cleanupMonsters();
    this.cleanupProjectiles();
    this.cleanupFoodDrops();
    if (this.chest) {
      this.chest.destroy();
      this.stage.scene.remove(this.chest.group);
      this.chest = null;
    }

    // Reset Hero Position to room entrance (South end)
    this.hero.setPosition(0, 6.5);
    this.stage.follow(0, 6.5, 1.0);

    // Spawn monsters via modular FloorDirector
    this.monsters = FloorDirector.spawnFloorMonsters(this.stage.scene, floorNumber);
    if (FloorDirector.isBossFloor(floorNumber)) {
      this.hero.showEmote('alert', 2.0);
    }

    this.callbacks.onFloorChange(this.floor);
    this.callbacks.onHpChange(this.hero.stats.hp, this.hero.stats.maxHp);
    this.callbacks.onGoldChange(this.hero.stats.gold);
    this.callbacks.onKillsChange(this.hero.stats.kills);
  }

  public spawnFoodDrop(posX: number, posZ: number, forceHighTier: boolean = false): void {
    this.foodIdCounter++;
    const pool = forceHighTier ? FOOD_CATALOG.slice(4) : FOOD_CATALOG.slice(0, 8);
    const chosen = pool[Math.floor(Math.random() * pool.length)];
    const drop = new FoodDrop3D(
      this.stage.scene,
      {
        ...chosen,
        id: `food_${this.foodIdCounter}`,
      },
      posX,
      posZ
    );
    this.foodDrops.push(drop);
  }

  private update(delta: number): void {
    if (this.isGameOver || this.isPaused) return;

    // 1. Room animations & portal pulse
    this.room.update(delta);

    // 2. Read Joystick input
    const inputVec = this.joystick.getVector();
    const isMoving = this.joystick.isMoving();

    const heroPos = this.hero.getPosition();

    if (isMoving) {
      const moveDist = this.hero.stats.moveSpeed * delta;
      const nextX = heroPos.x + inputVec.x * moveDist;
      const nextZ = heroPos.z + inputVec.y * moveDist;

      const clamped = this.room.clampPosition(nextX, nextZ);
      this.hero.setPosition(clamped.x, clamped.z);
      this.hero.move(inputVec.x, inputVec.y, delta);
    } else {
      this.hero.move(0, 0, delta);
    }

    // Run-and-Gun: Auto-aim and fire continuously while moving AND while standing still
    this.handleAutoAim(delta, this.hero.getPosition(), isMoving);

    // Hero visual update & swing
    this.hero.update(delta);

    // Camera smoothly follows hero
    this.stage.follow(heroPos.x, heroPos.z, delta);

    // 3. Update Monsters & Hero Collision via CollisionSystem
    CollisionSystem.resolveMonstersAndContact(
      delta,
      this.hero,
      this.monsters,
      this.stage.camera,
      (rawAtk, heroDied) => {
        this.callbacks.onHpChange(this.hero.stats.hp, this.hero.stats.maxHp);
        this.damageText.spawn(heroPos.x, 1.2, heroPos.z, `-${rawAtk}`, 'damage');
        if (heroDied) {
          this.handleGameOver();
        }
      }
    );

    if (this.isGameOver) return;

    // 4. Update Projectiles & Monster Collision via CollisionSystem
    this.projectiles = CollisionSystem.resolveProjectiles(
      delta,
      this.stage.scene,
      this.projectiles,
      this.monsters,
      (hitEvent) => this.handleProjectileHitEvent(hitEvent)
    );

    // 5. Update 3D Food Drops
    this.updateFoodDrops(delta, heroPos.x, heroPos.z);

    // 6. Update Loot Chest
    if (this.chest) {
      const result = this.chest.update(delta, heroPos.x, heroPos.z);
      if (result.opened) {
        this.hero.stats.gold += result.gold;
        this.runGoldEarned += result.gold;
        this.hero.heal(result.heal);
        this.hero.showEmote('cash', 1.8);
        this.damageText.spawn(
          this.chest.group.position.x,
          1.2,
          this.chest.group.position.z,
          `+${result.gold} GOLD`,
          'crit'
        );
        this.damageText.spawn(heroPos.x, 1.5, heroPos.z, `+${result.heal} HP`, 'heal');

        // Chest awards forging ores & magic crystal into capacity-limited backpack
        this.tryCollectLootIntoBackpack({
          resource_stone: 2,
          resource_crystal: 1,
        });

        this.spawnFoodDrop(
          this.chest.group.position.x + 1.1,
          this.chest.group.position.z + 0.5,
          true
        );

        this.callbacks.onGoldChange(this.hero.stats.gold);
        this.callbacks.onHpChange(this.hero.stats.hp, this.hero.stats.maxHp);
      }
    }

    // 7. Check Portal Entry
    if (this.isRoomCleared && this.room.checkPortalCollision(heroPos.x, heroPos.z)) {
      this.startFloor(this.floor + 1);
    }

    // 8. Update floating damage numbers
    this.damageText.update(delta);
  }

  /**
   * 嘗試將地下城戰利品放入隨身背包（嚴格遵守 12 格空間上限）
   */
  public tryCollectLootIntoBackpack(itemsToAdd: Record<string, number>): boolean {
    const cur = this.passportStorage.load();
    const res = SnekInventoryService.addItemsToBackpack(cur, itemsToAdd);
    this.passportStorage.save(res.passport);

    const used = SnekInventoryService.getBackpackUsedCount(res.passport);
    const cap = SnekInventoryService.getBackpackCapacity(res.passport);

    const addedEntries = Object.entries(res.addedItems);
    if (addedEntries.length > 0) {
      const [firstId, firstCount] = addedEntries[0];
      const name = ITEM_CATALOG[firstId]?.name || firstId;
      this.callbacks.onBackpackChange?.(used, cap, `+${firstCount} ${name}`);
    } else {
      this.callbacks.onBackpackChange?.(used, cap);
    }

    if (Object.keys(res.overflowItems).length > 0) {
      this.callbacks.onBackpackFull?.(used, cap);
      return false;
    }
    return true;
  }

  private updateFoodDrops(delta: number, heroX: number, heroZ: number): void {
    const remaining: FoodDrop3D[] = [];
    for (let i = 0; i < this.foodDrops.length; i++) {
      const drop = this.foodDrops[i];
      const picked = drop.update(delta, heroX, heroZ);
      if (picked) {
        const cfg = drop.config;
        if (cfg.effectType === 'MAX_HP') {
          this.hero.stats.maxHp += cfg.statBonus;
        } else if (cfg.effectType === 'ATK_UP') {
          this.hero.stats.atk += cfg.statBonus;
        } else if (cfg.effectType === 'SPEED_UP') {
          this.hero.stats.moveSpeed = Math.min(10.5, this.hero.stats.moveSpeed + cfg.statBonus);
        } else if (cfg.effectType === 'CRIT_UP') {
          this.hero.stats.critChance = Math.min(0.75, this.hero.stats.critChance + cfg.statBonus);
        } else if (cfg.effectType === 'WEAPON_UPGRADE') {
          this.hero.stats.atk += cfg.statBonus;
          const nextWeapon = this.hero.upgradeWeapon();
          this.callbacks.onWeaponChange?.(nextWeapon);
        }

        // 拾取地面食材時，將對應「生鮮食材 (raw_*)」放入隨身九宮格背包（需回廚房烹煮成料理）
        const rawIngredientId =
          cfg.effectType === 'WEAPON_UPGRADE' || cfg.healAmount >= 40
            ? 'raw_turkey'
            : cfg.effectType === 'ATK_UP'
              ? 'raw_ribs'
              : 'raw_apple';
        this.tryCollectLootIntoBackpack({ [rawIngredientId]: 1 });

        this.hero.heal(cfg.healAmount);
        this.damageText.spawn(heroX, 1.65, heroZ, `${cfg.name} (${cfg.effectLabel})`, 'heal');
        this.callbacks.onHpChange(this.hero.stats.hp, this.hero.stats.maxHp);
        this.callbacks.onFoodPickup?.(cfg);

        drop.destroy();
        this.stage.scene.remove(drop.group);
      } else {
        remaining.push(drop);
      }
    }
    this.foodDrops = remaining;
  }

  public handleAutoAim(
    delta: number,
    _heroPos: THREE.Vector3,
    isMoving: boolean = false
  ): void {
    const configs = this.combatSystem.updateAutoAimAndFire(
      delta,
      this.hero,
      this.monsters,
      isMoving
    );
    for (let i = 0; i < configs.length; i++) {
      this.projectiles.push(new Projectile3D(this.stage.scene, configs[i]));
    }
  }

  private handleProjectileHitEvent(event: ProjectileHitEvent): void {
    const { monster, actualDamage, isCrit, dead } = event;
    const mPos = monster.getPosition();
    const text = isCrit ? `CRIT! -${actualDamage}` : `-${actualDamage}`;
    this.damageText.spawn(
      mPos.x,
      monster.config.size * 1.5,
      mPos.z,
      text,
      isCrit ? 'crit' : 'damage'
    );

    if (dead) {
      const goldGain = Math.round(monster.config.expValue * 0.5);
      this.hero.stats.kills++;
      this.hero.stats.gold += goldGain;
      this.runGoldEarned += goldGain;
      this.callbacks.onKillsChange(this.hero.stats.kills);
      this.callbacks.onGoldChange(this.hero.stats.gold);

      if (monster.config.type === 'GOLEM_BOSS') {
        this.spawnFoodDrop(mPos.x, mPos.z, true);
        this.tryCollectLootIntoBackpack({
          resource_stone: 2,
          resource_crystal: 2,
        });
      } else {
        // Monsters have a chance to drop forging ore into personal backpack
        if (Math.random() < 0.45) {
          this.tryCollectLootIntoBackpack({ resource_stone: 1 });
        }
        const dropChance = SnekStatsContainer.computeDynamicDropChance(
          0.42,
          this.hero.stats.hp,
          this.hero.stats.maxHp
        );
        if (Math.random() < dropChance) {
          this.spawnFoodDrop(mPos.x, mPos.z, false);
        }
      }

      this.checkRoomClear();
    }
  }

  private checkRoomClear(): void {
    if (!this.isRoomCleared && FloorDirector.areAllMonstersDefeated(this.monsters)) {
      this.isRoomCleared = true;
      this.room.setPortalActive(true);
      this.hero.showEmote('happy', 1.8);

      this.chest = FloorDirector.spawnClearRewardChest(this.stage.scene, this.floor);

      // Persist floor clear milestone to SnekPetPassport via PortalHost
      this.portalHost.settleExpedition({
        worldId: 'dungeon3d',
        durationSec: 30,
        stageReached: this.floor,
        outcome: 'EXTRACTED',
        goldEarned: this.runGoldEarned,
        expEarned: 25 + this.floor * 10,
        killsCount: this.hero.stats.kills,
        itemsFound: {
          resource_stone: 1,
        },
        upgradedWeaponTier: this.hero.getCurrentWeapon().tier,
      });
      this.runGoldEarned = 0;

      this.callbacks.onRoomClear(this.floor);
    }
  }

  private handleGameOver(): void {
    this.isGameOver = true;
    this.joystick.resetControls();
    this.hero.showEmote('sleep', 2.5);

    this.portalHost.settleExpedition({
      worldId: 'dungeon3d',
      durationSec: 30,
      stageReached: this.floor,
      outcome: 'DEFEATED',
      goldEarned: this.runGoldEarned,
      expEarned: 10,
      killsCount: this.hero.stats.kills,
    });
    this.runGoldEarned = 0;

    this.callbacks.onGameOver(this.floor, this.hero.stats.kills, this.hero.stats.gold);
  }

  public restart(): void {
    this.isGameOver = false;
    this.runGoldEarned = 0;
    this.joystick.resetControls();
    const passport = this.passportStorage.load();
    const resolved = ArtisanForgeService.resolveCombatStats(passport);
    this.hero.applyResolvedCombatProfile(resolved);
    this.hero.stats.hp = this.hero.stats.maxHp;
    this.hero.stats.gold = 0;
    this.hero.stats.kills = 0;
    const w = this.hero.setWeaponTier(0);
    this.callbacks.onWeaponChange?.(w);
    this.startFloor(1);
  }

  private cleanupMonsters(): void {
    for (let i = 0; i < this.monsters.length; i++) {
      this.monsters[i].destroy();
      this.stage.scene.remove(this.monsters[i].group);
    }
    this.monsters = [];
  }

  private cleanupProjectiles(): void {
    for (let i = 0; i < this.projectiles.length; i++) {
      this.projectiles[i].destroy();
      this.stage.scene.remove(this.projectiles[i].group);
    }
    this.projectiles = [];
  }

  private cleanupFoodDrops(): void {
    for (let i = 0; i < this.foodDrops.length; i++) {
      this.foodDrops[i].destroy();
      this.stage.scene.remove(this.foodDrops[i].group);
    }
    this.foodDrops = [];
  }

  public destroy(): void {
    this.cleanupMonsters();
    this.cleanupProjectiles();
    this.cleanupFoodDrops();
    if (this.chest) {
      this.chest.destroy();
      this.stage.scene.remove(this.chest.group);
      this.chest = null;
    }
    this.hero.destroy();
    this.stage.scene.remove(this.hero.group);
    this.room.destroy();
    this.stage.scene.remove(this.room.group);
    this.damageText.destroy();
    this.joystick.destroy();
    this.stage.destroy();
  }
}
