import { SnekCoreStats } from '../types.ts';

export interface StatModifier {
  id: string;
  stat: keyof SnekCoreStats;
  flat?: number;
  percent?: number; // 例如 0.15 代表 +15%
  temporary: boolean; // true 代表副本內暫時料理/道具增益，回家時自動清除
}

/**
 * SnekPetSDK 五維屬性容器與動態平衡輔助器 (參考規格書 07 & 13)
 * 公式：Effective = (Base + sum(Flat)) * (1 + sum(Percent))
 */
export class SnekStatsContainer {
  private baseStats: SnekCoreStats;
  private modifiers: Map<string, StatModifier> = new Map();

  constructor(initialBase: SnekCoreStats) {
    this.baseStats = { ...initialBase };
  }

  public setBaseStats(nextBase: SnekCoreStats): void {
    this.baseStats = { ...nextBase };
  }

  public addModifier(mod: StatModifier): void {
    this.modifiers.set(mod.id, { ...mod });
  }

  public removeModifier(id: string): void {
    this.modifiers.delete(id);
  }

  /**
   * 規格書 07 (2.1)：清除副本內的暫時性增益，保留常駐基礎與工匠裝備修正
   */
  public clearTemporaryModifiers(): void {
    for (const [id, mod] of this.modifiers.entries()) {
      if (mod.temporary) {
        this.modifiers.delete(id);
      }
    }
  }

  public getEffectiveStat(statKey: keyof SnekCoreStats): number {
    const base = this.baseStats[statKey];
    let flatSum = 0;
    let percentSum = 0;

    for (const mod of this.modifiers.values()) {
      if (mod.stat === statKey) {
        flatSum += mod.flat || 0;
        percentSum += mod.percent || 0;
      }
    }

    const raw = (base + flatSum) * Math.max(0.1, 1 + percentSum);
    return statKey === 'speed' ? Number(raw.toFixed(2)) : Math.round(raw);
  }

  public getEffectiveStats(): SnekCoreStats {
    return {
      hp: this.getEffectiveStat('hp'),
      atk: this.getEffectiveStat('atk'),
      def: this.getEffectiveStat('def'),
      speed: this.getEffectiveStat('speed'),
      luck: this.getEffectiveStat('luck'),
    };
  }

  /**
   * 規格書 13 (PinchRescueRule)：當玩家生命值比例 <= 25% 時，提高食物/回血掉落率 1.65 倍
   */
  public static computeDynamicDropChance(
    baseChance: number,
    currentHp: number,
    maxHp: number
  ): number {
    const ratio = maxHp > 0 ? currentHp / maxHp : 1.0;
    const pinchMultiplier = ratio <= 0.25 ? 1.65 : 1.0;
    return Math.min(1.0, baseChance * pinchMultiplier);
  }
}
