import * as THREE from 'three';

interface FloatingNumber {
  el: HTMLDivElement;
  worldPos: THREE.Vector3;
  life: number;
  maxLife: number;
  offsetY: number;
}

export class DamageText3D {
  private containerEl: HTMLElement;
  private camera: THREE.Camera;
  private numbers: FloatingNumber[] = [];

  constructor(overlayContainer: HTMLElement, camera: THREE.Camera) {
    this.containerEl = overlayContainer;
    this.camera = camera;
  }

  public spawn(
    worldX: number,
    worldY: number,
    worldZ: number,
    text: string,
    type: 'damage' | 'crit' | 'heal' = 'damage'
  ): void {
    const el = document.createElement('div');
    el.className = `dungeon3d-dmg-text ${type}`;
    el.innerText = text;

    let color = '#ffffff';
    let fontSize = '16px';
    let textShadow = '0 0 6px rgba(0, 0, 0, 0.8)';

    if (type === 'crit') {
      color = '#ffd700';
      fontSize = '20px';
      textShadow = '0 0 10px rgba(255, 215, 0, 0.8), 0 0 4px #000';
    } else if (type === 'heal') {
      color = '#00e676';
      fontSize = '17px';
      textShadow = '0 0 8px rgba(0, 230, 118, 0.8), 0 0 4px #000';
    }

    el.style.cssText = `
      position: absolute;
      left: 0;
      top: 0;
      color: ${color};
      font-size: ${fontSize};
      font-weight: 900;
      font-family: system-ui, -apple-system, sans-serif;
      text-shadow: ${textShadow};
      pointer-events: none;
      transform: translate(-50%, -50%);
      will-change: transform, opacity;
      z-index: 30;
      transition: opacity 0.2s;
    `;

    this.containerEl.appendChild(el);

    this.numbers.push({
      el,
      worldPos: new THREE.Vector3(worldX, worldY, worldZ),
      life: 0.8,
      maxLife: 0.8,
      offsetY: 0,
    });
  }

  public update(delta: number): void {
    const rect = this.containerEl.getBoundingClientRect();
    const width = rect.width;
    const height = rect.height;
    if (width === 0 || height === 0) return;

    const remaining: FloatingNumber[] = [];

    for (let i = 0; i < this.numbers.length; i++) {
      const item = this.numbers[i];
      item.life -= delta;
      item.offsetY += delta * 1.5; // rise in 3D world space

      if (item.life <= 0) {
        if (item.el.parentElement) {
          item.el.parentElement.removeChild(item.el);
        }
        continue;
      }

      // Project world to screen
      const tempVec = new THREE.Vector3(
        item.worldPos.x,
        item.worldPos.y + item.offsetY,
        item.worldPos.z
      );
      tempVec.project(this.camera);

      // Check if behind camera
      if (tempVec.z > 1) {
        item.el.style.display = 'none';
      } else {
        item.el.style.display = 'block';
        const screenX = (tempVec.x * 0.5 + 0.5) * width;
        const screenY = (-(tempVec.y * 0.5) + 0.5) * height;

        const opacity = Math.min(1.0, item.life / (item.maxLife * 0.4));
        item.el.style.transform = `translate(${screenX}px, ${screenY}px) translate(-50%, -50%)`;
        item.el.style.opacity = `${opacity}`;
      }

      remaining.push(item);
    }

    this.numbers = remaining;
  }

  public destroy(): void {
    this.numbers.forEach((item) => {
      if (item.el.parentElement) {
        item.el.parentElement.removeChild(item.el);
      }
    });
    this.numbers = [];
  }
}
