import { ISkillCard, SkillCardContext } from '../ISkillCard.ts';

export class HedgeOptionsShieldCard implements ISkillCard {
  public readonly id = 'HEDGE_OPTIONS_SHIELD';
  public readonly title = '期權對沖烈焰盾';
  public readonly badge = '風險對沖';
  public readonly category = 'WEAPON';
  public readonly iconKey = 'shield';
  public readonly maxLevel = 10;
  public readonly financeTerm = '【對沖 (Hedging)】利用衍生品建立反向部位，以鎖定利潤並抵禦市場大跌風險。';

  public getDescription(currentLevel: number): string {
    const next = currentLevel + 1;
    if (next <= 4) return `建立對沖部位！旋轉期權護盾數量增至 ${next + 1} 顆`;
    if (next === 5) return '波動率溢價！旋轉速度提升 30%';
    if (next <= 7) return `多層保護傘！護盾數量增至 ${next} 顆`;
    if (next === 8) return '對沖屏障八重全開！護盾數量達 8 顆';
    if (next === 9) return '神聖對沖場！護盾防護半徑顯著擴大至 58px';
    return '終極零風險力場！防護半徑擴大至 70px 且反傷威力提升 50%';
  }

  public isEligible(context: SkillCardContext): boolean {
    const current = context.engine.skillLevels?.get(this.id) ?? 0;
    return current < this.maxLevel;
  }

  public apply(context: SkillCardContext, nextLevel: number): void {
    const orbiter = context.weaponManager?.orbiter;
    if (orbiter) {
      if (typeof orbiter.upgrade === 'function') orbiter.upgrade();
      if (nextLevel <= 4) {
        orbiter.count = Math.min(8, nextLevel + 1);
      } else if (nextLevel === 5) {
        orbiter.speed = (orbiter.speed || 0.05) + 0.02;
      } else if (nextLevel <= 7) {
        orbiter.count = Math.min(8, nextLevel);
      } else if (nextLevel === 8) {
        orbiter.count = 8;
      } else if (nextLevel === 9) {
        orbiter.radius = 58;
      } else if (nextLevel >= 10) {
        orbiter.radius = 70;
        orbiter.damage = (orbiter.damage || 1.8) * 1.5;
      }
    }
  }
}
