import * as THREE from 'three';
import { GLTFLoader, GLTF } from 'three/examples/jsm/loaders/GLTFLoader.js';
import * as SkeletonUtils from 'three/examples/jsm/utils/SkeletonUtils.js';

export interface ModelAnimationController {
  mixer: THREE.AnimationMixer;
  actions: Map<string, THREE.AnimationAction>;
  play: (name: string, fadeDuration?: number) => void;
  stop: () => void;
  update: (delta: number) => void;
}

export class GLTFModelLoader {
  private static instance: GLTFModelLoader | null = null;
  private loader: GLTFLoader;
  private cache: Map<string, Promise<GLTF>> = new Map();

  private constructor() {
    this.loader = new GLTFLoader();
  }

  public static getInstance(): GLTFModelLoader {
    if (!GLTFModelLoader.instance) {
      GLTFModelLoader.instance = new GLTFModelLoader();
    }
    return GLTFModelLoader.instance;
  }

  /**
   * Load and cache a glTF / glb file.
   */
  public async load(url: string): Promise<GLTF> {
    if (!this.cache.has(url)) {
      const promise = new Promise<GLTF>((resolve, reject) => {
        this.loader.load(
          url,
          (gltf) => {
            // Configure shadow casting and receiving on all child meshes
            gltf.scene.traverse((child) => {
              if (child instanceof THREE.Mesh) {
                child.castShadow = true;
                child.receiveShadow = true;
                if (child.material) {
                  child.material.side = THREE.DoubleSide;
                }
              }
            });
            resolve(gltf);
          },
          undefined,
          (err) => {
            reject(err);
          }
        );
      });
      this.cache.set(url, promise);
    }

    return this.cache.get(url)!;
  }

  /**
   * Instantiate a cloned copy of a loaded model for multi-instance use (e.g. multiple monsters).
   */
  public instantiate(gltf: GLTF): { scene: THREE.Object3D; animations: THREE.AnimationClip[] } {
    const clonedScene = SkeletonUtils.clone(gltf.scene);
    return {
      scene: clonedScene,
      animations: gltf.animations,
    };
  }

  /**
   * Create an AnimationController for a loaded model and its clips.
   */
  public createAnimationController(
    root: THREE.Object3D,
    clips: THREE.AnimationClip[]
  ): ModelAnimationController {
    const mixer = new THREE.AnimationMixer(root);
    const actions = new Map<string, THREE.AnimationAction>();

    clips.forEach((clip) => {
      const action = mixer.clipAction(clip);
      actions.set(clip.name.toLowerCase(), action);
    });

    let currentAction: THREE.AnimationAction | null = null;

    return {
      mixer,
      actions,
      play: (name: string, fadeDuration: number = 0.2) => {
        const nextAction = actions.get(name.toLowerCase());
        if (!nextAction || nextAction === currentAction) return;

        if (currentAction) {
          currentAction.fadeOut(fadeDuration);
        }

        nextAction.reset().fadeIn(fadeDuration).play();
        currentAction = nextAction;
      },
      stop: () => {
        if (currentAction) {
          currentAction.stop();
          currentAction = null;
        }
      },
      update: (delta: number) => {
        mixer.update(delta);
      },
    };
  }

  public clearCache(): void {
    this.cache.clear();
  }
}
